// Command pattern parser for v2 DSL.
// Task 2.1: Implement command pattern parser (literals, `or`, `regex`)

use may_i_core::v2::pattern::CommandPattern;
use may_i_sexpr::{RawError, Sexpr};

/// Parse a command pattern from an s-expression.
///
/// Syntax:
/// - `"git"` - literal match
/// - `(or "git" "gh")` - matches any of the listed commands
/// - `(regex "^git.*$")` - regex match
pub fn parse_command_pattern(sexpr: &Sexpr) -> Result<CommandPattern, RawError> {
    match sexpr {
        Sexpr::Atom(s, _) => {
            // Literal command name
            Ok(CommandPattern::Literal(s.clone()))
        }
        Sexpr::List(list, span) => {
            if list.is_empty() {
                return Err(RawError::new("empty command pattern", *span));
            }

            let tag = list[0].as_atom().ok_or_else(|| {
                RawError::new("command pattern tag must be an atom", list[0].span())
            })?;

            match tag {
                "or" => {
                    // Parse OR pattern: (or PATTERN ...)
                    if list.len() < 2 {
                        return Err(RawError::new("or must have at least one pattern", *span));
                    }

                    let patterns: Result<Vec<CommandPattern>, _> =
                        list[1..].iter().map(parse_command_pattern).collect();

                    Ok(CommandPattern::Or(patterns?))
                }
                "regex" => {
                    // Parse regex pattern: (regex PATTERN)
                    if list.len() != 2 {
                        return Err(RawError::new(
                            "regex must have exactly one pattern string",
                            *span,
                        ));
                    }

                    let pattern_str = list[1].as_atom().ok_or_else(|| {
                        RawError::new("regex pattern must be a string", list[1].span())
                    })?;

                    let regex = regex::Regex::new(pattern_str).map_err(|e| {
                        RawError::new(format!("invalid regex pattern: {e}"), list[1].span())
                    })?;

                    Ok(CommandPattern::Regex(regex))
                }
                other => Err(RawError::new(
                    format!("unknown command pattern form: {other}"),
                    list[0].span(),
                )
                .with_help("valid command patterns: literal string, (or ...), (regex ...)")),
            }
        }
        Sexpr::Vector(_, span) => Err(RawError::new(
            "command pattern does not support vector syntax",
            *span,
        )),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn parse(input: &str) -> Result<CommandPattern, RawError> {
        let (forms, errors) = may_i_sexpr::parse(input);
        if let Some(err) = errors.into_iter().next() {
            return Err(err);
        }
        if forms.len() != 1 {
            return Err(RawError::new(
                "expected exactly one form",
                may_i_core::Span::new(0, input.len()),
            ));
        }
        parse_command_pattern(&forms[0])
    }

    #[test]
    fn parse_literal_command() {
        let pattern = parse(r#""git""#).unwrap();
        match pattern {
            CommandPattern::Literal(s) => assert_eq!(s, "git"),
            _ => panic!("expected Literal"),
        }
    }

    #[test]
    fn parse_or_command() {
        let pattern = parse(r#"(or "git" "gh")"#).unwrap();
        match pattern {
            CommandPattern::Or(patterns) => {
                assert_eq!(patterns.len(), 2);
                assert!(matches!(&patterns[0], CommandPattern::Literal(s) if s == "git"));
                assert!(matches!(&patterns[1], CommandPattern::Literal(s) if s == "gh"));
            }
            _ => panic!("expected Or"),
        }
    }

    #[test]
    fn parse_regex_command() {
        let pattern = parse(r#"(regex "^git.*$")"#).unwrap();
        match pattern {
            CommandPattern::Regex(re) => {
                assert!(re.is_match("git-log"));
                assert!(!re.is_match("hg"));
            }
            _ => panic!("expected Regex"),
        }
    }

    #[test]
    fn nested_or_patterns() {
        let pattern = parse(r#"(or "git" (or "gh" "hub"))"#).unwrap();
        match pattern {
            CommandPattern::Or(patterns) => {
                assert_eq!(patterns.len(), 2);
                assert!(matches!(&patterns[0], CommandPattern::Literal(s) if s == "git"));
                // Second element is also an Or
                assert!(matches!(&patterns[1], CommandPattern::Or(_)));
            }
            _ => panic!("expected Or"),
        }
    }

    #[test]
    fn invalid_regex_is_error() {
        let err = parse(r#"(regex "[invalid")"#).expect_err("expected error");
        assert!(format!("{err}").contains("invalid regex"));
    }
}

// Config parser for v2 DSL.
// Task 2.10: Implement safe-env-vars and check parsers (preserve existing behavior)

use may_i_core::Span;
use may_i_core::types::{ContextFacts, Decision};
use may_i_core::v2::ast::{Check, Config, SecurityConfig};
use may_i_sexpr::{RawError, Sexpr};

/// Parse a v2 config from an s-expression string.
pub fn parse_config(input: &str) -> Result<Config, RawError> {
    let (forms, errors) = may_i_sexpr::parse(input);
    if let Some(err) = errors.into_iter().next() {
        return Err(err);
    }

    let mut config = Config::default();

    for form in &forms {
        let list = form
            .as_list()
            .ok_or_else(|| RawError::new("top-level form must be a list", form.span()))?;

        if list.is_empty() {
            return Err(RawError::new("empty top-level form", form.span()));
        }

        let tag = list[0]
            .as_atom()
            .ok_or_else(|| RawError::new("form tag must be an atom", list[0].span()))?;

        match tag {
            "rule" => {
                let rule = super::rule::parse_rule(form)?;
                config.rules.push(rule.value);
            }
            "define" => {
                let define = super::rule::parse_define(form)?;
                config.defines.push(define);
            }
            "safe-env-vars" => {
                parse_safe_env_vars(&list[1..], &mut config.security, form.span())?;
            }
            "check" => {
                let checks = parse_check(&list[1..], form.span())?;
                config.checks.extend(checks);
            }
            other => {
                return Err(RawError::new(
                    format!("unknown top-level form: {other}"),
                    list[0].span(),
                )
                .with_help("valid top-level forms: rule, define, safe-env-vars, check"));
            }
        }
    }

    Ok(config)
}

/// Parse safe-env-vars form: (safe-env-vars "VAR1" "VAR2" ...)
fn parse_safe_env_vars(
    args: &[Sexpr],
    security: &mut SecurityConfig,
    _span: Span,
) -> Result<(), RawError> {
    for item in args {
        let s = item
            .as_atom()
            .ok_or_else(|| RawError::new("safe-env-vars entry must be a string", item.span()))?;
        security.safe_env_vars.insert(s.to_string());
    }
    Ok(())
}

/// Parse check form: (check DECISION "cmd" ...)
/// Supports nested with-facts: (check (with-facts [[:key]] :allow "cmd"))
fn parse_check(args: &[Sexpr], check_span: Span) -> Result<Vec<Check>, RawError> {
    let mut checks = Vec::new();
    let mut i = 0;

    while i < args.len() {
        // Check for with-facts wrapper
        if let Some(list) = args[i].as_list()
            && let Some("with-facts") = list.first().and_then(Sexpr::as_atom)
        {
            let with_facts_checks = parse_with_facts(list, &ContextFacts::default(), check_span)?;
            checks.extend(with_facts_checks);
            i += 1;
            continue;
        }

        // Parse decision keyword
        let expected = match args[i].as_atom().ok_or_else(|| {
            RawError::new(
                "check entries must start with a decision keyword (:allow, :deny, :ask) or with-facts",
                args[i].span(),
            )
        })? {
            ":allow" => Decision::Allow,
            ":deny" => Decision::Deny,
            ":ask" => Decision::Ask,
            other => {
                return Err(RawError::new(
                    format!("unknown expected decision: {other}"),
                    args[i].span(),
                )
                .with_help("valid decisions: :allow, :deny, :ask"));
            }
        };
        i += 1;

        // Parse command
        if i >= args.len() {
            return Err(RawError::new(
                "check must provide a command after each decision",
                check_span,
            )
            .with_help("use :allow \"cmd\" or (with-facts [[:key]] :allow \"cmd\")"));
        }

        let cmd = args[i]
            .as_atom()
            .ok_or_else(|| RawError::new("check command must be a string", args[i].span()))?;

        checks.push(Check {
            command: cmd.to_string(),
            expected,
            context: ContextFacts::default(),
            span: args[i].span(),
        });
        i += 1;
    }

    Ok(checks)
}

/// Parse with-facts form: (with-facts [[:key] [:key "value"]] :allow "cmd" ...)
fn parse_with_facts(
    list: &[Sexpr],
    inherited: &ContextFacts,
    check_span: Span,
) -> Result<Vec<Check>, RawError> {
    if list.len() < 2 {
        return Err(RawError::new(
            "with-facts must have a fact vector",
            list.first().map_or(Span::new(0, 0), Sexpr::span),
        )
        .with_help("use (with-facts [[:client/opencode]] :allow \"cmd\")"));
    }

    let facts = parse_fact_literal(&list[1])?;
    let merged = inherited.merge(&facts);

    // Parse remaining check items with merged context
    parse_check_items(&list[2..], &merged, check_span)
}

/// Parse fact literal vector: [[:key] [:key "value"]]
fn parse_fact_literal(sexpr: &Sexpr) -> Result<ContextFacts, RawError> {
    let items = match sexpr {
        Sexpr::Vector(items, _) => items,
        _ => {
            return Err(RawError::new(
                "with-facts requires a fact vector",
                sexpr.span(),
            ));
        }
    };

    let mut facts = ContextFacts::default();
    for item in items {
        let (key, value) = parse_fact_entry(item)?;
        if facts.has(&key) {
            return Err(RawError::new(
                format!("duplicate fact key in with-facts: {key}"),
                item.span(),
            ));
        }
        match value {
            Some(value) => facts.insert_scalar(key, value),
            None => facts.insert_present(key),
        }
    }

    Ok(facts)
}

/// Parse a single fact entry: [:key] or [:key "value"]
fn parse_fact_entry(entry: &Sexpr) -> Result<(String, Option<String>), RawError> {
    let items = match entry {
        Sexpr::Vector(items, _) => items,
        _ => {
            return Err(RawError::new(
                "fact entries must be vectors like [:key] or [:key \"value\"]",
                entry.span(),
            ));
        }
    };

    if items.is_empty() || items.len() > 2 {
        return Err(RawError::new(
            "fact entries must have exactly a key or a key and value",
            entry.span(),
        ));
    }

    let key = parse_context_key(&items[0])?;
    let value = if items.len() == 2 {
        Some(
            items[1]
                .as_atom()
                .ok_or_else(|| {
                    RawError::new("context fact value must be a string", items[1].span())
                })?
                .to_string(),
        )
    } else {
        None
    };

    Ok((key, value))
}

/// Parse a context key (namespaced atom starting with ':').
fn parse_context_key(sexpr: &Sexpr) -> Result<String, RawError> {
    let key = sexpr
        .as_atom()
        .ok_or_else(|| RawError::new("context fact key must be an atom", sexpr.span()))?;

    if !key.starts_with(':') {
        return Err(RawError::new(
            format!("context fact key must be namespaced: {key}"),
            sexpr.span(),
        )
        .with_help("use a namespaced key like :via/ssh or :claude-code/permission-mode"));
    }

    Ok(key.to_string())
}

/// Parse check items with a given context.
fn parse_check_items(
    items: &[Sexpr],
    context: &ContextFacts,
    check_span: Span,
) -> Result<Vec<Check>, RawError> {
    let mut checks = Vec::new();
    let mut i = 0;

    while i < items.len() {
        // Check for nested with-facts
        if let Some(list) = items[i].as_list()
            && let Some("with-facts") = list.first().and_then(Sexpr::as_atom)
        {
            let nested_checks = parse_with_facts(list, context, check_span)?;
            checks.extend(nested_checks);
            i += 1;
            continue;
        }

        // Parse decision
        let expected = match items[i].as_atom().ok_or_else(|| {
            RawError::new(
                "check entries must start with a decision keyword or with-facts",
                items[i].span(),
            )
        })? {
            ":allow" => Decision::Allow,
            ":deny" => Decision::Deny,
            ":ask" => Decision::Ask,
            other => {
                return Err(RawError::new(
                    format!("unknown expected decision: {other}"),
                    items[i].span(),
                )
                .with_help("valid decisions: :allow, :deny, :ask"));
            }
        };
        i += 1;

        // Parse command
        if i >= items.len() {
            return Err(RawError::new(
                "check must provide a command after each decision",
                check_span,
            ));
        }

        let cmd = items[i]
            .as_atom()
            .ok_or_else(|| RawError::new("check command must be a string", items[i].span()))?;

        checks.push(Check {
            command: cmd.to_string(),
            expected,
            context: context.clone(),
            span: items[i].span(),
        });
        i += 1;
    }

    Ok(checks)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parse_empty_config() {
        let config = parse_config("").unwrap();
        assert!(config.rules.is_empty());
        assert!(config.defines.is_empty());
        assert!(config.security.safe_env_vars.is_empty());
        assert!(config.checks.is_empty());
    }

    #[test]
    fn parse_safe_env_vars() {
        let config = parse_config(r#"(safe-env-vars "HOME" "USER" "PATH")"#).unwrap();
        assert!(config.security.safe_env_vars.contains("HOME"));
        assert!(config.security.safe_env_vars.contains("USER"));
        assert!(config.security.safe_env_vars.contains("PATH"));
        assert_eq!(config.security.safe_env_vars.len(), 3);
    }

    #[test]
    fn parse_simple_check() {
        let config = parse_config(r#"(check :allow "git status" :deny "rm -rf /")"#).unwrap();
        assert_eq!(config.checks.len(), 2);
        assert_eq!(config.checks[0].command, "git status");
        assert!(matches!(config.checks[0].expected, Decision::Allow));
        assert_eq!(config.checks[1].command, "rm -rf /");
        assert!(matches!(config.checks[1].expected, Decision::Deny));
    }

    #[test]
    fn parse_check_with_ask() {
        let config = parse_config(r#"(check :ask "ssh prod-server")"#).unwrap();
        assert_eq!(config.checks.len(), 1);
        assert!(matches!(config.checks[0].expected, Decision::Ask));
    }

    #[test]
    fn parse_check_with_with_facts() {
        let config = parse_config(
            r#"
            (check
                (with-facts [[:client/opencode] [:via/ssh]]
                    :allow "git push"))
        "#,
        )
        .unwrap();
        assert_eq!(config.checks.len(), 1);
        assert!(config.checks[0].context.has(":client/opencode"));
        assert!(config.checks[0].context.has(":via/ssh"));
    }

    #[test]
    fn parse_nested_with_facts() {
        let config = parse_config(
            r#"
            (check
                (with-facts [[:client/opencode]]
                    (with-facts [[:via/ssh]]
                        :allow "git push")))
        "#,
        )
        .unwrap();
        assert_eq!(config.checks.len(), 1);
        assert!(config.checks[0].context.has(":client/opencode"));
        assert!(config.checks[0].context.has(":via/ssh"));
    }

    #[test]
    fn parse_check_with_fact_values() {
        let config = parse_config(
            r#"
            (check
                (with-facts [[:opencode/agent "build"]]
                    :allow "npm install"))
        "#,
        )
        .unwrap();
        assert_eq!(config.checks.len(), 1);
        // The context should have the scalar value
        assert!(config.checks[0].context.has(":opencode/agent"));
    }

    #[test]
    fn safe_env_vars_accepts_strings() {
        // Atoms are strings in sexpr, so "123" is a valid env var name
        let config = parse_config(r#"(safe-env-vars "123" "HOME")"#).unwrap();
        assert!(config.security.safe_env_vars.contains("123"));
        assert!(config.security.safe_env_vars.contains("HOME"));
    }

    #[test]
    fn check_rejects_invalid_decision() {
        let err = parse_config(r#"(check :invalid "cmd")"#).expect_err("expected error");
        assert!(format!("{err}").contains("unknown expected decision"));
    }

    #[test]
    fn check_accepts_string_commands() {
        // Atoms are strings in sexpr
        let config = parse_config(r#"(check :allow "git status" :deny "rm")"#).unwrap();
        assert_eq!(config.checks.len(), 2);
        assert_eq!(config.checks[0].command, "git status");
        assert_eq!(config.checks[1].command, "rm");
    }

    #[test]
    fn check_requires_command_after_decision() {
        let err = parse_config(r#"(check :allow)"#).expect_err("expected error");
        assert!(format!("{err}").contains("provide a command"));
    }

    #[test]
    fn duplicate_fact_key_is_error() {
        let err = parse_config(
            r#"
            (check
                (with-facts [[:client/opencode] [:client/opencode]]
                    :allow "cmd"))
        "#,
        )
        .expect_err("expected error");
        assert!(format!("{err}").contains("duplicate fact key"));
    }

    #[test]
    fn fact_key_must_be_namespaced() {
        let err = parse_config(
            r#"
            (check
                (with-facts [[invalid-key]]
                    :allow "cmd"))
        "#,
        )
        .expect_err("expected error");
        assert!(format!("{err}").contains("namespaced"));
    }

    #[test]
    fn full_config_example() {
        // Note: named predicate references (like 'safe-git) are not yet implemented
        // They will be implemented in task 3.x (define resolution)
        let config = parse_config(
            r#"
            (safe-env-vars "HOME" "USER")

            (define safe-git
                (or (positional "status") (positional "log")))

            (rule "git" (or (positional "status") (positional "log")) (effect :allow))
            (rule "git" (positional "push") (effect :ask))

            (check
                :allow "git status"
                (with-facts [[:client/opencode]] :allow "git push")
                :deny "rm -rf /")
        "#,
        )
        .unwrap();

        assert_eq!(config.security.safe_env_vars.len(), 2);
        assert_eq!(config.defines.len(), 1);
        assert_eq!(config.rules.len(), 2);
        assert_eq!(config.checks.len(), 3);
    }
}

// Effect parser for v2 DSL.
// Task 2.6: Implement effect parser (`effect`, `may-i`, `case`, `when`, `unless`, `if`)

use may_i_core::v2::ast::{Effect, Spanned};
use may_i_sexpr::{RawError, Sexpr};

/// Parse an effect from an s-expression list.
///
/// Syntax:
/// - `(effect :allow)` or `(effect :allow "reason")`
/// - `(effect :ask)` or `(effect :ask "reason")`
/// - `(effect :deny)` or `(effect :deny "reason")`
/// - `(may-i PATTERN)` - recursive evaluation
/// - `(case [(PREDICATE EFFECT) ...] [ELSE-EFFECT])`
/// - `(when PREDICATE EFFECT)`
/// - `(unless PREDICATE EFFECT)`
/// - `(if PREDICATE THEN-EFFECT [ELSE-EFFECT])`
pub fn parse_effect(sexpr: &Sexpr) -> Result<Spanned<Effect>, RawError> {
    let list = sexpr
        .as_list()
        .ok_or_else(|| RawError::new("effect must be a list", sexpr.span()))?;

    if list.is_empty() {
        return Err(RawError::new("empty effect", sexpr.span()));
    }

    let tag = list[0]
        .as_atom()
        .ok_or_else(|| RawError::new("effect tag must be an atom", list[0].span()))?;

    let effect = match tag {
        "effect" => parse_terminal_effect(&list[1..], sexpr.span())?,
        "may-i" => parse_may_i(&list[1..], sexpr.span())?,
        "case" => parse_case(&list[1..], sexpr.span())?,
        "when" => parse_when(&list[1..], sexpr.span())?,
        "unless" => parse_unless(&list[1..], sexpr.span())?,
        "if" => parse_if(&list[1..], sexpr.span())?,
        other => {
            return Err(
                RawError::new(format!("unknown effect form: {other}"), list[0].span())
                    .with_help("valid effects: effect, may-i, case, when, unless, if"),
            );
        }
    };

    Ok(Spanned::new(effect, sexpr.span()))
}

/// Parse a terminal effect (allow, ask, deny).
fn parse_terminal_effect(args: &[Sexpr], span: may_i_core::Span) -> Result<Effect, RawError> {
    if args.is_empty() {
        return Err(RawError::new(
            "effect must have a keyword (:allow, :ask, or :deny)",
            span,
        ));
    }

    let kw = args[0]
        .as_atom()
        .ok_or_else(|| RawError::new("effect keyword must be an atom", args[0].span()))?;

    let reason = if args.len() > 1 {
        Some(
            args[1]
                .as_atom()
                .ok_or_else(|| RawError::new("effect reason must be a string", args[1].span()))?
                .to_string(),
        )
    } else {
        None
    };

    match kw {
        ":allow" => Ok(Effect::Allow(reason)),
        ":ask" => Ok(Effect::Ask(reason)),
        ":deny" => Ok(Effect::Deny(reason)),
        other => Err(
            RawError::new(format!("unknown effect keyword: {other}"), args[0].span())
                .with_help("valid effect keywords: :allow, :ask, :deny"),
        ),
    }
}

/// Parse a recursive evaluation effect.
fn parse_may_i(args: &[Sexpr], span: may_i_core::Span) -> Result<Effect, RawError> {
    if args.len() != 1 {
        return Err(RawError::new(
            "may-i must have exactly one argument pattern",
            span,
        ));
    }

    let pattern = super::pattern::parse_arg_pattern(&args[0])?;
    Ok(Effect::Evaluate(pattern))
}

/// Parse a case expression.
fn parse_case(args: &[Sexpr], span: may_i_core::Span) -> Result<Effect, RawError> {
    if args.is_empty() {
        return Err(RawError::new("case must have at least one branch", span));
    }

    let mut branches = Vec::new();
    let mut fallback = None;

    for (i, arg) in args.iter().enumerate() {
        let branch_list = arg
            .as_list()
            .ok_or_else(|| RawError::new("case branch must be a list", arg.span()))?;

        if branch_list.is_empty() {
            return Err(RawError::new("empty case branch", arg.span()));
        }

        // Check for else branch
        if let Some(tag) = branch_list[0].as_atom()
            && tag == "else"
        {
            if i != args.len() - 1 {
                return Err(RawError::new(
                    "else branch must be the last branch",
                    arg.span(),
                ));
            }
            let else_effect = if branch_list.len() == 2 {
                parse_effect(&branch_list[1])?
            } else {
                return Err(RawError::new(
                    "else branch must have exactly one effect",
                    arg.span(),
                ));
            };
            fallback = Some(Box::new(else_effect));
            continue;
        }

        // Regular branch: (PREDICATE EFFECT)
        if branch_list.len() != 2 {
            return Err(RawError::new(
                "case branch must have exactly a predicate and an effect",
                arg.span(),
            ));
        }

        let predicate = super::predicate::parse_predicate(&branch_list[0])?;
        let effect = parse_effect(&branch_list[1])?;

        branches.push((Spanned::new(predicate, branch_list[0].span()), effect));
    }

    Ok(Effect::Case { branches, fallback })
}

/// Parse a when expression.
fn parse_when(args: &[Sexpr], span: may_i_core::Span) -> Result<Effect, RawError> {
    if args.len() != 2 {
        return Err(RawError::new(
            "when must have exactly a predicate and an effect: (when PREDICATE EFFECT)",
            span,
        ));
    }

    let predicate = super::predicate::parse_predicate(&args[0])?;
    let effect = parse_effect(&args[1])?;

    Ok(Effect::When {
        predicate: Spanned::new(predicate, args[0].span()),
        effect: Box::new(effect),
    })
}

/// Parse an unless expression.
fn parse_unless(args: &[Sexpr], span: may_i_core::Span) -> Result<Effect, RawError> {
    if args.len() != 2 {
        return Err(RawError::new(
            "unless must have exactly a predicate and an effect: (unless PREDICATE EFFECT)",
            span,
        ));
    }

    let predicate = super::predicate::parse_predicate(&args[0])?;
    let effect = parse_effect(&args[1])?;

    Ok(Effect::Unless {
        predicate: Spanned::new(predicate, args[0].span()),
        effect: Box::new(effect),
    })
}

/// Parse an if expression.
fn parse_if(args: &[Sexpr], span: may_i_core::Span) -> Result<Effect, RawError> {
    if args.len() < 2 || args.len() > 3 {
        return Err(RawError::new(
            "if must have 2 or 3 arguments: (if PREDICATE THEN-EFFECT [ELSE-EFFECT])",
            span,
        ));
    }

    let predicate = super::predicate::parse_predicate(&args[0])?;
    let then_effect = parse_effect(&args[1])?;
    let else_effect = if args.len() == 3 {
        Some(Box::new(parse_effect(&args[2])?))
    } else {
        None
    };

    Ok(Effect::If {
        predicate: Spanned::new(predicate, args[0].span()),
        then_effect: Box::new(then_effect),
        else_effect,
    })
}

