            }
            _ => panic!("expected Positional"),
        }
    }

    #[test]
    fn parse_positional_with_wildcard() {
        let pattern = parse_arg(r#"(positional "push" *)"#).unwrap();
        match pattern {
            ArgPattern::Positional(pargs) => {
