        match pattern {
            ArgPattern::Exact(pargs) => {
                assert_eq!(pargs.len(), 1);
            }
            _ => panic!("expected Exact"),
        }
    }

    #[test]
    fn parse_anywhere_pattern() {
        let pattern = parse_arg(r#"(anywhere "--force")"#).unwrap();
        match pattern {
            ArgPattern::Anywhere(exprs) => {
                assert_eq!(exprs.len(), 1);
            }
            _ => panic!("expected Anywhere"),
        }
    }

    #[test]
    fn parse_forbidden_pattern() {
        let pattern = parse_arg(r#"(forbidden "--force")"#).unwrap();
        match pattern {
            ArgPattern::Forbidden(exprs) => {
                assert_eq!(exprs.len(), 1);
            }
            _ => panic!("expected Forbidden"),
        }
    }

    #[test]
    fn parse_at_position() {
        let pattern = parse_arg(r#"(= 1 "git")"#).unwrap();
        match pattern {
            ArgPattern::At { position, .. } => {
                assert_eq!(position, 1);
            }
            _ => panic!("expected At"),
        }
    }

    #[test]
    fn positional_with_quantifiers() {
        let pattern = parse_arg(r#"(positional "cmd" (? "arg") (+ "more"))"#).unwrap();
        match pattern {
            ArgPattern::Positional(pargs) => {
                assert_eq!(pargs.len(), 3);
                assert!(matches!(pargs[0].quantifier, Quantifier::One));
                assert!(matches!(pargs[1].quantifier, Quantifier::Optional));
                assert!(matches!(pargs[2].quantifier, Quantifier::OneOrMore));
            }
            _ => panic!("expected Positional"),
        }
    }

    #[test]
    fn position_zero_is_error() {
        let err = parse_arg(r#"(= 0 "test")"#).expect_err("expected error");
        assert!(format!("{err}").contains("1 or greater"));
    }
}

// Unified predicate parser for v2 DSL.
// Task 2.2: Implement fact query parser for `(has ...)` forms
// Task 2.4: Implement boolean combinator parsers (`and`, `or`, `not`)
// Task 2.5: Implement unified predicate parser that dispatches to fact or arg parsers

use may_i_core::types::FactQuery;
use may_i_core::v2::predicate::Predicate;
use may_i_sexpr::{RawError, Sexpr};

/// Parse a unified predicate from an s-expression.
///
/// This is the main entry point for predicate parsing. It handles:
/// - Fact queries: `(has FACT-QUERY)`
/// - Argument patterns: `(positional ...)`, `(exact ...)`, etc.
/// - Boolean combinators: `(and PREDICATE ...)`, `(or PREDICATE ...)`, `(not PREDICATE)`
/// - Named predicate references (will be resolved later)
pub fn parse_predicate(sexpr: &Sexpr) -> Result<Predicate, RawError> {
    // If it's an atom, it's a named predicate reference
    if let Some(name) = sexpr.as_atom() {
        // Named predicate reference - will be resolved during validation
        return Ok(Predicate::Named(name.to_string()));
    }

    let list = sexpr
        .as_list()
        .ok_or_else(|| RawError::new("predicate must be a list or atom reference", sexpr.span()))?;

    if list.is_empty() {
        return Err(RawError::new("empty predicate", sexpr.span()));
    }

    let tag = list[0]
        .as_atom()
        .ok_or_else(|| RawError::new("predicate tag must be an atom", list[0].span()))?;

    match tag {
        // Fact query
        "has" => {
            if list.len() != 2 {
                return Err(RawError::new(
                    "has must have exactly one fact query",
                    sexpr.span(),
                ));
            }
            let query = parse_fact_query(&list[1])?;
            Ok(Predicate::Has(query))
        }

        // Boolean combinators
        "and" => {
            if list.len() < 2 {
                return Err(RawError::new(
                    "and must have at least one predicate",
                    sexpr.span(),
                ));
            }
            let predicates: Result<Vec<Predicate>, _> =
                list[1..].iter().map(parse_predicate).collect();
            Ok(Predicate::And(predicates?))
        }
        "or" => {
            if list.len() < 2 {
                return Err(RawError::new(
                    "or must have at least one predicate",
                    sexpr.span(),
                ));
            }
            let predicates: Result<Vec<Predicate>, _> =
                list[1..].iter().map(parse_predicate).collect();
            Ok(Predicate::Or(predicates?))
        }
        "not" => {
            if list.len() != 2 {
                return Err(RawError::new(
                    "not must have exactly one predicate",
                    sexpr.span(),
                ));
            }
            let inner = parse_predicate(&list[1])?;
            Ok(Predicate::Not(Box::new(inner)))
        }

        // Argument patterns - delegate to the argument pattern parser
        "positional" | "exact" | "anywhere" | "forbidden" | "=" => {
            let arg_pattern = super::pattern::parse_arg_pattern(sexpr)?;
            Ok(Predicate::Arg(arg_pattern))
        }

        other => Err(
            RawError::new(format!("unknown predicate form: {other}"), list[0].span()).with_help(
                "valid predicates: has, and, or, not, positional, exact, anywhere, forbidden, =",
            ),
        ),
    }
}

/// Parse a fact query from an s-expression.
///
/// Syntax:
/// - `:key` or `[:key]` - presence check
/// - `[:key PATTERN]` - value check with pattern
fn parse_fact_query(sexpr: &Sexpr) -> Result<FactQuery, RawError> {
    // Bare atom: presence check without vector syntax
    if sexpr.as_atom().is_some() {
        let key = parse_context_key(sexpr)?;
        return Ok(FactQuery::Presence {
            key,
            vector_syntax: false,
        });
    }

    // Vector syntax: presence or value check
    let items = match sexpr {
        Sexpr::Vector(items, _) => items,
        _ => {
            return Err(RawError::new(
                "fact query must be a namespaced key or vector like [:key] or [:key pattern]",
                sexpr.span(),
            ));
        }
    };

    match items.len() {
        1 => {
            let key = parse_context_key(&items[0])?;
            Ok(FactQuery::Presence {
                key,
                vector_syntax: true,
            })
        }
        2 => {
            let key = parse_context_key(&items[0])?;
            let pattern = parse_fact_pattern(&items[1])?;
            Ok(FactQuery::Value { key, pattern })
        }
        _ => Err(RawError::new(
            "fact query vectors must contain a key or a key and value pattern",
            sexpr.span(),
        )),
    }
}

/// Parse a context key (namespaced atom starting with ':').
fn parse_context_key(sexpr: &Sexpr) -> Result<String, RawError> {
    let key = sexpr
        .as_atom()
        .ok_or_else(|| RawError::new("context fact key must be an atom", sexpr.span()))?;

    if !key.starts_with(':') {
        return Err(RawError::new(
            format!("context fact key must be namespaced: {key}"),
            sexpr.span(),
        )
        .with_help("use a namespaced key like :via/ssh or :claude-code/permission-mode"));
    }

    Ok(key.to_string())
}

/// Parse a fact pattern for value matching.
use may_i_core::types::FactPattern;

fn parse_fact_pattern(sexpr: &Sexpr) -> Result<FactPattern, RawError> {
    match sexpr {
        Sexpr::Atom(s, _) if s == "*" => Ok(FactPattern::Wildcard),
        Sexpr::Atom(s, _) => Ok(FactPattern::Literal(s.clone())),
        Sexpr::List(list, span) => {
            if list.is_empty() {
                return Err(RawError::new("empty fact pattern", *span));
            }

            let tag = list[0]
                .as_atom()
                .ok_or_else(|| RawError::new("fact pattern tag must be an atom", list[0].span()))?;

            match tag {
                "regex" => {
                    if list.len() != 2 {
                        return Err(RawError::new("regex must have exactly one pattern", *span));
                    }
                    let pat = list[1].as_atom().ok_or_else(|| {
                        RawError::new("regex pattern must be a string", list[1].span())
                    })?;
                    let re = regex::Regex::new(pat).map_err(|err| {
                        RawError::new(format!("invalid regex '{pat}': {err}"), list[1].span())
                    })?;
                    Ok(FactPattern::Regex(re))
                }
                "and" => {
                    if list.len() < 2 {
                        return Err(RawError::new("and must have at least one pattern", *span));
                    }
                    let patterns: Result<Vec<_>, _> =
                        list[1..].iter().map(parse_fact_pattern).collect();
                    Ok(FactPattern::And(patterns?))
                }
                "or" => {
                    if list.len() < 2 {
                        return Err(RawError::new("or must have at least one pattern", *span));
                    }
                    let patterns: Result<Vec<_>, _> =
                        list[1..].iter().map(parse_fact_pattern).collect();
                    Ok(FactPattern::Or(patterns?))
                }
                "not" => {
                    if list.len() != 2 {
                        return Err(RawError::new("not must have exactly one pattern", *span));
                    }
                    let inner = parse_fact_pattern(&list[1])?;
                    Ok(FactPattern::Not(Box::new(inner)))
                }
                other => Err(RawError::new(
                    format!("unknown fact pattern: {other}"),
                    list[0].span(),
                )
                .with_help("valid fact patterns: string, *, regex, and, or, not")),
            }
        }
        Sexpr::Vector(_, span) => Err(RawError::new(
            "fact patterns do not support nested vector syntax",
            *span,
        )),
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use may_i_core::v2::pattern::ArgPattern;

    fn parse_pred(input: &str) -> Result<Predicate, RawError> {
        let (forms, errors) = may_i_sexpr::parse(input);
        if let Some(err) = errors.into_iter().next() {
            return Err(err);
        }
        if forms.len() != 1 {
            return Err(RawError::new(
                "expected exactly one form",
                may_i_core::Span::new(0, input.len()),
            ));
        }
        parse_predicate(&forms[0])
    }

    #[test]
    fn parse_has_presence_bare() {
        let pred = parse_pred(r#"(has :via/ssh)"#).unwrap();
        match pred {
            Predicate::Has(FactQuery::Presence { key, vector_syntax }) => {
                assert_eq!(key, ":via/ssh");
                assert!(!vector_syntax);
            }
            _ => panic!("expected Has with Presence"),
        }
    }

    #[test]
    fn parse_has_presence_vector() {
        let pred = parse_pred(r#"(has [:via/ssh])"#).unwrap();
        match pred {
            Predicate::Has(FactQuery::Presence { key, vector_syntax }) => {
                assert_eq!(key, ":via/ssh");
                assert!(vector_syntax);
            }
            _ => panic!("expected Has with Presence"),
        }
    }

    #[test]
    fn parse_has_value() {
        let pred = parse_pred(r#"(has [:opencode/agent "build"])"#).unwrap();
        match pred {
            Predicate::Has(FactQuery::Value { key, pattern }) => {
                assert_eq!(key, ":opencode/agent");
                assert!(matches!(pattern, FactPattern::Literal(s) if s == "build"));
            }
            _ => panic!("expected Has with Value"),
        }
    }

    #[test]
    fn parse_and_predicate() {
        let pred = parse_pred(r#"(and (has :via/ssh) (positional "push"))"#).unwrap();
        match pred {
            Predicate::And(preds) => {
                assert_eq!(preds.len(), 2);
                assert!(matches!(preds[0], Predicate::Has(_)));
                assert!(matches!(preds[1], Predicate::Arg(_)));
            }
            _ => panic!("expected And"),
        }
    }

    #[test]
    fn parse_or_predicate() {
        let pred = parse_pred(r#"(or (has :client/claude-code) (has :client/opencode))"#).unwrap();
        match pred {
            Predicate::Or(preds) => {
                assert_eq!(preds.len(), 2);
            }
            _ => panic!("expected Or"),
        }
    }

    #[test]
    fn parse_not_predicate() {
        let pred = parse_pred(r#"(not (has :dangerous))"#).unwrap();
        match pred {
            Predicate::Not(inner) => {
                assert!(matches!(inner.as_ref(), Predicate::Has(_)));
            }
            _ => panic!("expected Not"),
        }
    }

    #[test]
    fn nested_boolean_combinators() {
        let pred = parse_pred(
            r#"
            (and
                (has :via/ssh)
                (or (positional "push")
                    (positional "pull")))
        "#,
        )
        .unwrap();

        match pred {
            Predicate::And(preds) => {
                assert_eq!(preds.len(), 2);
                assert!(matches!(preds[1], Predicate::Or(_)));
            }
            _ => panic!("expected And"),
        }
    }

    #[test]
    fn non_namespaced_key_is_error() {
        let err = parse_pred(r#"(has invalid-key)"#).expect_err("expected error");
        assert!(format!("{err}").contains("namespaced"));
    }

    #[test]
    fn parse_named_predicate_reference() {
        let pred = parse_pred(r#"safe-git"#).unwrap();
        match pred {
            Predicate::Named(name) => {
                assert_eq!(name, "safe-git");
            }
            _ => panic!("expected Named, got {:?}", pred),
        }
    }

    #[test]
    fn parse_has_with_regex() {
        let pred = parse_pred(r#"(has [:ssh/host (regex "^prod-")])"#).unwrap();
        match pred {
            Predicate::Has(FactQuery::Value { key, pattern }) => {
                assert_eq!(key, ":ssh/host");
                assert!(matches!(pattern, FactPattern::Regex(_)));
            }
            _ => panic!("expected Has with Regex Value"),
        }
    }

    #[test]
    fn parse_has_with_wildcard() {
        let pred = parse_pred(r#"(has [:ssh/host *])"#).unwrap();
        match pred {
            Predicate::Has(FactQuery::Value { key, pattern }) => {
                assert_eq!(key, ":ssh/host");
                assert!(matches!(pattern, FactPattern::Wildcard));
            }
            _ => panic!("expected Has with Wildcard Value"),
        }
    }

    #[test]
    fn parse_and_preserves_single_predicate() {
        // Parser preserves (and X) as And([X]), doesn't flatten
        let pred = parse_pred(r#"(and (has :via/ssh))"#).unwrap();
        match pred {
            Predicate::And(preds) => {
                assert_eq!(preds.len(), 1);
            }
            _ => panic!("expected And with single element"),
        }
    }

    #[test]
    fn parse_or_preserves_single_predicate() {
        // Parser preserves (or X) as Or([X]), doesn't flatten
        let pred = parse_pred(r#"(or (has :via/ssh))"#).unwrap();
        match pred {
            Predicate::Or(preds) => {
                assert_eq!(preds.len(), 1);
            }
            _ => panic!("expected Or with single element"),
        }
    }

    #[test]
    fn parse_deeply_nested_combinators() {
        let pred = parse_pred(
            r#"
            (or
                (and
                    (has :via/ssh)
                    (not (positional "--force")))
                (and
                    (has :local)
                    (positional "--safe")))
        "#,
        )
        .unwrap();

        match pred {
            Predicate::Or(preds) => {
                assert_eq!(preds.len(), 2);
                assert!(matches!(preds[0], Predicate::And(_)));
                assert!(matches!(preds[1], Predicate::And(_)));
            }
            _ => panic!("expected Or"),
        }
    }

    #[test]
    fn parse_arg_predicate_positional() {
        let pred = parse_pred(r#"(positional "push")"#).unwrap();
        match pred {
            Predicate::Arg(ArgPattern::Positional(_)) => {}
            _ => panic!("expected Arg with Positional"),
        }
    }

    #[test]
    fn parse_arg_predicate_exact() {
        let pred = parse_pred(r#"(exact "status")"#).unwrap();
        match pred {
            Predicate::Arg(ArgPattern::Exact(_)) => {}
            _ => panic!("expected Arg with Exact"),
        }
    }

    #[test]
    fn parse_arg_predicate_anywhere() {
        let pred = parse_pred(r#"(anywhere "--force")"#).unwrap();
        match pred {
            Predicate::Arg(ArgPattern::Anywhere(_)) => {}
            _ => panic!("expected Arg with Anywhere"),
        }
    }

    #[test]
    fn parse_arg_predicate_forbidden() {
        let pred = parse_pred(r#"(forbidden "--dangerous")"#).unwrap();
        match pred {
            Predicate::Arg(ArgPattern::Forbidden(_)) => {}
            _ => panic!("expected Arg with Forbidden"),
        }
    }
}

// Define resolution and validation for v2 DSL.
// Tasks 3.1-3.5: Build resolution map, detect duplicates, undefined refs, cycles, and resolve.

use may_i_core::span::Span;
use may_i_core::v2::ast::{Define, Rule, Spanned};
use may_i_core::v2::predicate::Predicate;
use std::collections::{HashMap, HashSet};

/// A resolution error with source span information.
#[derive(Debug, Clone)]
pub struct ResolutionError {
    pub message: String,
    pub span: Span,
    pub help: Option<String>,
}

impl ResolutionError {
    pub fn new(message: impl Into<String>, span: Span) -> Self {
        Self {
            message: message.into(),
            span,
            help: None,
        }
    }

    pub fn with_help(mut self, help: impl Into<String>) -> Self {
        self.help = Some(help.into());
        self
    }
}

impl std::fmt::Display for ResolutionError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}", self.message)?;
        if let Some(help) = &self.help {
            write!(f, "\n  help: {help}")?;
        }
        Ok(())
    }
}

impl std::error::Error for ResolutionError {}

/// Map of define names to their definitions.
#[derive(Debug, Clone, Default)]
pub struct DefineMap {
    /// Name -> (index in original defines list, span)
    indices: HashMap<String, (usize, Span)>,
}

impl DefineMap {
    /// Create a new define map from a list of defines.
    /// Returns an error if there are duplicate names.
    pub fn from_defines(defines: &[Define]) -> Result<Self, ResolutionError> {
        let mut indices: HashMap<String, (usize, Span)> = HashMap::new();

        for (idx, define) in defines.iter().enumerate() {
            if let Some((_, existing_span)) = indices.get(&define.name) {
                return Err(ResolutionError::new(
                    format!(
                        "duplicate define name: '{}' (first defined at byte offset {})",
                        define.name, existing_span.start
                    ),
                    define.span,
                )
                .with_help(
                    "each (define ...) must have a unique name, consider renaming this one"
                        .to_string(),
                ));
            }
            indices.insert(define.name.clone(), (idx, define.span));
        }

        Ok(Self { indices })
    }

    /// Check if a name is defined.
    pub fn contains(&self, name: &str) -> bool {
        self.indices.contains_key(name)
    }

    /// Get the define index and span for a name.
    pub fn get(&self, name: &str) -> Option<(usize, Span)> {
        self.indices.get(name).copied()
    }

    /// Get all defined names.
    pub fn names(&self) -> impl Iterator<Item = &String> {
        self.indices.keys()
    }
}

/// Information about a predicate reference.
#[derive(Debug, Clone)]
pub struct NamedRef {
    pub name: String,
    pub span: Span,
}

/// Collect all named predicate references from a predicate.
pub fn collect_named_refs(predicate: &Spanned<Predicate>) -> Vec<NamedRef> {
    let mut refs = Vec::new();
    collect_refs_recursive(&predicate.value, predicate.span, &mut refs);
    refs
}

fn collect_refs_recursive(predicate: &Predicate, span: Span, refs: &mut Vec<NamedRef>) {
    match predicate {
        Predicate::Named(name) => {
            refs.push(NamedRef {
                name: name.clone(),
                span,
            });
        }
        Predicate::And(predicates) | Predicate::Or(predicates) => {
            for p in predicates {
                collect_refs_recursive(p, span, refs);
            }
        }
        Predicate::Not(inner) => {
            collect_refs_recursive(inner, span, refs);
        }
        _ => {} // Has and Arg don't contain nested predicates
    }
}

/// Detect cycles in define references using DFS.
pub fn detect_cycles(defines: &[Define], define_map: &DefineMap) -> Result<(), ResolutionError> {
    // Build adjacency list: name -> names it references
    let mut adjacency: HashMap<String, Vec<String>> = HashMap::new();

    for define in defines {
        let refs = collect_named_refs(&define.predicate);
        let ref_names: Vec<String> = refs.into_iter().map(|r| r.name).collect();
        adjacency.insert(define.name.clone(), ref_names);
    }

    // DFS to detect cycles
    let mut visiting = HashSet::new();
    let mut visited = HashSet::new();

    for name in define_map.names() {
        if !visited.contains(name) {
            dfs_check_cycle(name, &adjacency, &mut visiting, &mut visited, define_map)?;
        }
    }

    Ok(())
}

fn dfs_check_cycle(
    name: &str,
    adjacency: &HashMap<String, Vec<String>>,
    visiting: &mut HashSet<String>,
    visited: &mut HashSet<String>,
    define_map: &DefineMap,
) -> Result<(), ResolutionError> {
    visiting.insert(name.to_string());

    if let Some(neighbors) = adjacency.get(name) {
        for neighbor in neighbors {
            if visiting.contains(neighbor) {
                // Found a cycle
                let (_, span) = define_map.get(name).unwrap();
                return Err(ResolutionError::new(
                    format!("cyclic define reference detected: '{name}' -> '{neighbor}'"),
                    span,
                )
                .with_help("predicates cannot reference each other in a cycle"));
            }

            if !visited.contains(neighbor) {
                dfs_check_cycle(neighbor, adjacency, visiting, visited, define_map)?;
            }
        }
    }

    visiting.remove(name);
    visited.insert(name.to_string());
    Ok(())
}

/// Check for undefined predicate references in a list of rules and defines.
pub fn check_undefined_refs(
    rules: &[Rule],
    defines: &[Define],
    define_map: &DefineMap,
) -> Result<(), ResolutionError> {
    // Collect all defined names
    let defined_names: HashSet<String> = define_map.names().cloned().collect();

    // Check references in defines
    for define in defines {
        let refs = collect_named_refs(&define.predicate);
        for named_ref in refs {
            if !defined_names.contains(&named_ref.name) {
                return Err(ResolutionError::new(
                    format!("undefined predicate reference: '{}'", named_ref.name),
                    named_ref.span,
                )
                .with_help(format!(
                    "define '{}' before using it, or check for typos",
                    named_ref.name
                )));
            }
        }
    }

    // Check references in rules
    for rule in rules {
        for predicate in &rule.predicates {
            let refs = collect_named_refs(predicate);
            for named_ref in refs {
                if !defined_names.contains(&named_ref.name) {
                    return Err(ResolutionError::new(
                        format!(
                            "undefined predicate reference: '{}' in rule for '{}'",
                            named_ref.name,
                            format_command_pattern(&rule.command.value)
                        ),
                        named_ref.span,
                    )
                    .with_help(format!(
                        "define '{}' before using it, or check for typos",
                        named_ref.name
                    )));
                }
            }
        }
    }

    Ok(())
}

fn format_command_pattern(pattern: &may_i_core::v2::pattern::CommandPattern) -> String {
    use may_i_core::v2::pattern::CommandPattern;
    match pattern {
        CommandPattern::Literal(s) => s.clone(),
        CommandPattern::Regex(_) => "(regex ...)".to_string(),
        CommandPattern::Or(_) => "(or ...)".to_string(),
    }
}

/// Resolve all named predicates by inlining their definitions.
/// Returns a new list of rules with all named predicates resolved.
pub fn resolve_predicates(
    rules: &[Rule],
    defines: &[Define],
    define_map: &DefineMap,
) -> Result<Vec<Rule>, ResolutionError> {
    rules
        .iter()
        .map(|rule| resolve_rule_predicates(rule, defines, define_map))
        .collect()
}

fn resolve_rule_predicates(
    rule: &Rule,
    defines: &[Define],
    define_map: &DefineMap,
) -> Result<Rule, ResolutionError> {
    let resolved_predicates: Result<Vec<_>, _> = rule
        .predicates
        .iter()
        .map(|p| resolve_single_predicate(p, defines, define_map))
        .collect();

    Ok(Rule {
        command: rule.command.clone(),
        predicates: resolved_predicates?,
        effect: rule.effect.clone(),
        span: rule.span,
    })
}

fn resolve_single_predicate(
    predicate: &Spanned<Predicate>,
    defines: &[Define],
    define_map: &DefineMap,
) -> Result<Spanned<Predicate>, ResolutionError> {
    let resolved = match &predicate.value {
        Predicate::Named(name) => {
            // Get the define and inline it
            if let Some((idx, _)) = define_map.get(name) {
                // Clone the predicate from the define (we keep the original span)
                defines[idx].predicate.value.clone()
            } else {
                // This shouldn't happen if we checked for undefined refs first
                return Err(ResolutionError::new(
                    format!("internal error: undefined predicate '{name}'"),
                    predicate.span,
                ));
            }
        }
        Predicate::And(predicates) => {
            let resolved: Result<Vec<_>, _> = predicates
                .iter()
                .map(|p| {
                    resolve_single_predicate(
                        &Spanned::new(p.clone(), predicate.span),
                        defines,
                        define_map,
                    )
                })
                .collect();
            Predicate::And(resolved?.into_iter().map(|s| s.value).collect())
        }
        Predicate::Or(predicates) => {
            let resolved: Result<Vec<_>, _> = predicates
                .iter()
                .map(|p| {
                    resolve_single_predicate(
                        &Spanned::new(p.clone(), predicate.span),
                        defines,
                        define_map,
                    )
                })
                .collect();
            Predicate::Or(resolved?.into_iter().map(|s| s.value).collect())
        }
        Predicate::Not(inner) => {
            let resolved = resolve_single_predicate(
                &Spanned::new(inner.as_ref().clone(), predicate.span),
                defines,
                define_map,
            )?;
            Predicate::Not(Box::new(resolved.value))
        }
        other => other.clone(),
    };

    Ok(Spanned::new(resolved, predicate.span))
}

/// Full validation pipeline for defines and rules.
/// Performs all validation checks in the correct order.
pub fn validate_and_resolve(
    rules: &[Rule],
    defines: &[Define],
) -> Result<(Vec<Rule>, DefineMap), Vec<ResolutionError>> {
    let mut errors = Vec::new();

    // Step 1: Build define map and check for duplicates (3.1, 3.2)
    let define_map = match DefineMap::from_defines(defines) {
        Ok(map) => map,
        Err(e) => {
            errors.push(e);
            return Err(errors);
        }
    };

    // Step 2: Check for undefined references (3.3)
    if let Err(e) = check_undefined_refs(rules, defines, &define_map) {
        errors.push(e);
        return Err(errors);
    }

    // Step 3: Detect cycles (3.4)
    if let Err(e) = detect_cycles(defines, &define_map) {
        errors.push(e);
        return Err(errors);
    }

    // Step 4: Resolve named predicates (3.5)
    let resolved_rules = match resolve_predicates(rules, defines, &define_map) {
        Ok(rules) => rules,
        Err(e) => {
            errors.push(e);
            return Err(errors);
        }
    };

    Ok((resolved_rules, define_map))
}

#[cfg(test)]
mod tests {
    use super::*;
    use may_i_core::v2::ast::{Define, Effect, Rule};
    use may_i_core::v2::pattern::CommandPattern;

    fn dummy_span() -> Span {
        Span::new(0, 0)
    }

    fn create_rule(predicates: Vec<Predicate>) -> Rule {
        Rule {
            command: Spanned::new(CommandPattern::Literal("test".to_string()), dummy_span()),
            predicates: predicates
                .into_iter()
                .map(|p| Spanned::new(p, dummy_span()))
                .collect(),
            effect: Spanned::new(Effect::Allow(None), dummy_span()),
            span: dummy_span(),
        }
    }

    fn create_define(name: &str, predicate: Predicate) -> Define {
        Define {
            name: name.to_string(),
            predicate: Spanned::new(predicate, dummy_span()),
            span: dummy_span(),
        }
    }

    #[test]
    fn detect_duplicate_defines() {
        let defines = vec![
            create_define("foo", Predicate::has_presence(":x")),
            create_define("foo", Predicate::has_presence(":y")),
        ];

        let result = DefineMap::from_defines(&defines);
        assert!(result.is_err());
        assert!(result.unwrap_err().message.contains("duplicate"));
    }

    #[test]
    fn detect_undefined_reference() {
        let defines = vec![];
        let rules = vec![create_rule(vec![Predicate::Named("undefined".to_string())])];
        let define_map = DefineMap::default();

        let result = check_undefined_refs(&rules, &defines, &define_map);
        assert!(result.is_err());
        assert!(result.unwrap_err().message.contains("undefined"));
    }

    #[test]
    fn detect_direct_cycle() {
        let defines = vec![
            create_define("a", Predicate::Named("b".to_string())),
            create_define("b", Predicate::Named("a".to_string())),
        ];
        let define_map = DefineMap::from_defines(&defines).unwrap();

        let result = detect_cycles(&defines, &define_map);
        assert!(result.is_err());
        assert!(result.unwrap_err().message.contains("cyclic"));
    }

    #[test]
    fn detect_indirect_cycle() {
        let defines = vec![
            create_define("a", Predicate::Named("b".to_string())),
            create_define("b", Predicate::Named("c".to_string())),
            create_define("c", Predicate::Named("a".to_string())),
        ];
        let define_map = DefineMap::from_defines(&defines).unwrap();

        let result = detect_cycles(&defines, &define_map);
        assert!(result.is_err());
        assert!(result.unwrap_err().message.contains("cyclic"));
    }

    #[test]
    fn resolve_simple_named_predicate() {
        let defines = vec![create_define("safe", Predicate::has_presence(":safe"))];
        let rules = vec![create_rule(vec![Predicate::Named("safe".to_string())])];
        let define_map = DefineMap::from_defines(&defines).unwrap();

        let resolved = resolve_predicates(&rules, &defines, &define_map).unwrap();
        assert_eq!(resolved.len(), 1);
        // After resolution, the Named predicate should be replaced with Has
        assert!(matches!(resolved[0].predicates[0].value, Predicate::Has(_)));
    }

    #[test]
    fn resolve_nested_predicate() {
        let defines = vec![
            create_define("a", Predicate::has_presence(":a")),
            create_define(
                "b",
                Predicate::And(vec![
                    Predicate::Named("a".to_string()),
                    Predicate::has_presence(":b"),
                ]),
            ),
        ];
        let rules = vec![create_rule(vec![Predicate::Named("b".to_string())])];
        let define_map = DefineMap::from_defines(&defines).unwrap();

        let resolved = resolve_predicates(&rules, &defines, &define_map).unwrap();
        assert!(matches!(resolved[0].predicates[0].value, Predicate::And(_)));
    }
}

// Rule and define parser for v2 DSL.
// Task 2.8: Implement rule parser with simplified syntax
// Task 2.9: Implement define parser for named predicates

use may_i_core::v2::ast::{Define, Rule, Spanned};
use may_i_sexpr::{RawError, Sexpr};

/// Parse a rule from an s-expression.
///
/// Syntax: `(rule COMMAND-PATTERN PREDICATE* EFFECT)`
///
/// Examples:
/// - `(rule "git" (effect :allow))` - allow all git commands
/// - `(rule "git" (positional "push") (effect :ask))` - ask for git push
/// - `(rule "git" (and (has :via/ssh) (positional "push")) (effect :allow))`
/// - `(rule (or "git" "gh") (effect :allow))` - allow git or gh
pub fn parse_rule(sexpr: &Sexpr) -> Result<Spanned<Rule>, RawError> {
    let list = sexpr
        .as_list()
        .ok_or_else(|| RawError::new("rule must be a list", sexpr.span()))?;

    if list.len() < 2 {
        return Err(RawError::new(
            "rule must have at least a command pattern and an effect",
            sexpr.span(),
        ));
    }

    // Parse command pattern (position 1 in the list, after "rule")
    let command = super::command::parse_command_pattern(&list[1])?;
    let command_spanned = Spanned::new(command, list[1].span());

    // Parse predicates (all but the last element)
    let mut predicates = Vec::new();
    let effect_idx = list.len() - 1;

    for predicate_sexpr in list.iter().take(effect_idx).skip(2) {
        let predicate = super::predicate::parse_predicate(predicate_sexpr)?;
        predicates.push(Spanned::new(predicate, predicate_sexpr.span()));
    }

    // Parse effect (last element)
    let effect = super::effect::parse_effect(&list[effect_idx])?;

    let rule = Rule::new(command_spanned, predicates, effect, sexpr.span());

    Ok(Spanned::new(rule, sexpr.span()))
}

/// Parse a named predicate definition from an s-expression.
///
/// Syntax: `(define NAME PREDICATE)`
///
/// Examples:
/// - `(define remote-prod (and (has :via/ssh) (has [:ssh/host (regex "^prod-")])))`
/// - `(define safe-cmd (or (positional "status") (positional "log")))`
pub fn parse_define(sexpr: &Sexpr) -> Result<Define, RawError> {
    let list = sexpr
        .as_list()
        .ok_or_else(|| RawError::new("define must be a list", sexpr.span()))?;

    if list.len() != 3 {
        return Err(RawError::new(
            "define must have exactly a name and a predicate",
            sexpr.span(),
        ));
    }

    // Parse name
    let name = list[1]
        .as_atom()
        .ok_or_else(|| RawError::new("define name must be an atom", list[1].span()))?;

    // Check for reserved names
    if is_reserved_define_name(name) {
        return Err(
            RawError::new(format!("reserved predicate name: {name}"), list[1].span())
                .with_help("choose a different name"),
        );
    }

    // Parse predicate
    let predicate = super::predicate::parse_predicate(&list[2])?;

    Ok(Define::new(
        name.to_string(),
        Spanned::new(predicate, list[2].span()),
        sexpr.span(),
    ))
}

/// Check if a name is reserved and cannot be used for defines.
fn is_reserved_define_name(name: &str) -> bool {
    matches!(
        name,
        "rule"
            | "define"
            | "has"
            | "and"
            | "or"
            | "not"
            | "positional"
            | "exact"
            | "anywhere"
            | "forbidden"
            | "="
            | "effect"
            | "may-i"
            | "case"
            | "when"
            | "unless"
            | "if"
            | "safe-env-vars"
            | "check"
            | "wrapper"
    )
}

#[cfg(test)]
