    fn parse_rule_str(input: &str) -> Result<Rule, RawError> {
        let (forms, errors) = may_i_sexpr::parse(input);
        if let Some(err) = errors.into_iter().next() {
            return Err(err);
        }
        if forms.len() != 1 {
            return Err(RawError::new(
                "expected exactly one form",
                Span::new(0, input.len()),
            ));
        }
        parse_rule(&forms[0]).map(|s| s.value)
    }

    fn parse_define_str(input: &str) -> Result<Define, RawError> {
        let (forms, errors) = may_i_sexpr::parse(input);
        if let Some(err) = errors.into_iter().next() {
            return Err(err);
        }
        if forms.len() != 1 {
            return Err(RawError::new(
                "expected exactly one form",
                Span::new(0, input.len()),
            ));
        }
        parse_define(&forms[0])
    }

    #[test]
    fn parse_simple_rule() {
        let rule = parse_rule_str(r#"(rule "git" (effect :allow))"#).unwrap();
        assert!(matches!(rule.command.value, CommandPattern::Literal(ref s) if s == "git"));
        assert!(rule.predicates.is_empty());
        assert!(rule.effect.value.is_terminal());
    }

    #[test]
    fn parse_rule_with_predicate() {
        let rule = parse_rule_str(r#"(rule "git" (positional "push") (effect :ask))"#).unwrap();
        assert!(matches!(rule.command.value, CommandPattern::Literal(ref s) if s == "git"));
        assert_eq!(rule.predicates.len(), 1);
        assert!(matches!(rule.predicates[0].value, Predicate::Arg(_)));
    }

    #[test]
    fn parse_rule_with_multiple_predicates() {
        let rule = parse_rule_str(
            r#"
            (rule "git"
                (has :via/ssh)
                (positional "push")
                (effect :allow))
        "#,
        )
        .unwrap();
        assert_eq!(rule.predicates.len(), 2);
    }

    #[test]
    fn parse_rule_with_or_command() {
        let rule = parse_rule_str(r#"(rule (or "git" "gh") (effect :allow))"#).unwrap();
        assert!(matches!(rule.command.value, CommandPattern::Or(_)));
    }

    #[test]
    fn parse_simple_define() {
        let def = parse_define_str(
            r#"
            (define remote-prod (and (has :via/ssh) (has [:ssh/host "prod-1"])))
        "#,
        )
        .unwrap();
        assert_eq!(def.name, "remote-prod");
        assert!(matches!(def.predicate.value, Predicate::And(_)));
    }

    #[test]
    fn reserved_name_is_error() {
        let err = parse_define_str(r#"(define has (has :via/ssh))"#).expect_err("expected error");
        assert!(format!("{err}").contains("reserved"));
    }

    #[test]
    fn rule_without_enough_args_is_error() {
        let err = parse_rule_str(r#"(rule "git")"#).expect_err("expected error");
        assert!(format!("{err}").contains("effect must be a list"));
    }

    #[test]
    fn parse_rule_with_regex_command() {
        let rule = parse_rule_str(r#"(rule (regex "^git") (effect :allow))"#).unwrap();
        assert!(matches!(rule.command.value, CommandPattern::Regex(_)));
    }

    #[test]
    fn parse_rule_with_complex_predicates() {
        let rule = parse_rule_str(
            r#"
            (rule "git"
                (and
                    (has :via/ssh)
                    (or (positional "push") (positional "pull")))
                (effect :ask))
        "#,
        )
        .unwrap();
        assert_eq!(rule.predicates.len(), 1);
        match &rule.predicates[0].value {
            Predicate::And(preds) => assert_eq!(preds.len(), 2),
            _ => panic!("expected And predicate"),
        }
    }

    #[test]
    fn parse_rule_with_when_effect() {
        let rule = parse_rule_str(
            r#"
            (rule "git"
                (when (has :via/ssh) (effect :allow)))
        "#,
        )
        .unwrap();
        assert!(matches!(rule.effect.value, Effect::When { .. }));
    }

    #[test]
    fn parse_rule_with_case_effect() {
        let rule = parse_rule_str(
            r#"
            (rule "git"
                (case
                    [(positional "status") (effect :allow)]
                    [(positional "push") (effect :ask)]
                    [else (effect :deny)]))
        "#,
        )
        .unwrap();
        assert!(matches!(rule.effect.value, Effect::Case { .. }));
    }

    #[test]
    fn parse_define_with_named_reference() {
        let def = parse_define_str(
            r#"
            (define complex
                (and safe-git (has :via/ssh)))
        "#,
        )
        .unwrap();
        match &def.predicate.value {
            Predicate::And(preds) => {
                assert_eq!(preds.len(), 2);
                assert!(matches!(preds[0], Predicate::Named(_)));
                assert!(matches!(preds[1], Predicate::Has(_)));
            }
            _ => panic!("expected And with Named reference"),
        }
    }

    #[test]
    fn invalid_rule_missing_effect_is_error() {
        // (invalid "form") is parsed as a rule with "invalid" as command and "form" as predicate
        // but it's missing the required effect
        let err = parse_rule_str(r#"(invalid "form")"#).expect_err("expected error");
        assert!(format!("{err}").contains("effect"));
    }
}

// Annotated s-expression tree based on a recursion scheme.
//
// `DocF<R>` is the base functor (one layer of tree structure).
// `Doc<A>`  is the fixpoint, pairing each node with an annotation `A`.

/// One layer of s-expression structure, parameterized over what sits
/// in recursive positions.
#[derive(Debug, Clone)]
pub enum DocF<R> {
    Atom(String),
    List(Vec<R>),
    Vector(Vec<R>),
}

impl<R> DocF<R> {
    /// Functor map: transform children (recursive positions).
    pub fn map<S>(self, mut f: impl FnMut(R) -> S) -> DocF<S> {
        match self {
            DocF::Atom(s) => DocF::Atom(s),
            DocF::List(rs) => DocF::List(rs.into_iter().map(&mut f).collect()),
            DocF::Vector(rs) => DocF::Vector(rs.into_iter().map(&mut f).collect()),
        }
    }

    /// Functor map by reference.
    pub fn map_ref<S>(&self, mut f: impl FnMut(&R) -> S) -> DocF<S> {
        match self {
            DocF::Atom(s) => DocF::Atom(s.clone()),
            DocF::List(rs) => DocF::List(rs.iter().map(&mut f).collect()),
            DocF::Vector(rs) => DocF::Vector(rs.iter().map(&mut f).collect()),
        }
    }

    pub fn as_atom(&self) -> Option<&str> {
        match self {
            DocF::Atom(s) => Some(s),
            _ => None,
        }
    }

    pub fn children(&self) -> Option<&[R]> {
        match self {
            DocF::List(cs) | DocF::Vector(cs) => Some(cs),
            _ => None,
        }
    }
}

/// Layout hint for the pretty-printer.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub enum LayoutHint {
    /// Let the pretty-printer decide flat vs broken.
    #[default]
    Auto,
    /// Always break children to separate lines.
    AlwaysBreak,
}

/// An annotated s-expression tree — the fixpoint of `DocF` where each
/// node carries an annotation of type `A`.
///
/// `Doc<()>` is the unannotated tree used for parsing and rendering.
#[derive(Debug, Clone)]
pub struct Doc<A = ()> {
    pub ann: A,
    pub node: DocF<Doc<A>>,
    pub layout: LayoutHint,
    /// Render this subtree in dimmed style (for unevaluated content).
    pub dimmed: bool,
}

// ── Constructors (unannotated) ─────────────────────────────────────

impl Doc<()> {
    pub fn atom(s: impl Into<String>) -> Self {
        Doc {
            ann: (),
            node: DocF::Atom(s.into()),
            layout: LayoutHint::Auto,
            dimmed: false,
        }
    }

    pub fn list(children: Vec<Doc<()>>) -> Self {
        Doc {
            ann: (),
            node: DocF::List(children),
            layout: LayoutHint::Auto,
            dimmed: false,
        }
    }

    pub fn vector(children: Vec<Doc<()>>) -> Self {
        Doc {
            ann: (),
            node: DocF::Vector(children),
            layout: LayoutHint::Auto,
            dimmed: false,
        }
    }

    /// Create a list node that always breaks to separate lines.
    pub fn broken_list(children: Vec<Doc<()>>) -> Self {
        Doc {
            ann: (),
            node: DocF::List(children),
            layout: LayoutHint::AlwaysBreak,
            dimmed: false,
        }
    }
}

// ── Accessors ──────────────────────────────────────────────────────

impl<A> Doc<A> {
    pub fn as_atom(&self) -> Option<&str> {
        self.node.as_atom()
    }

    pub fn children(&self) -> Option<&[Doc<A>]> {
        self.node.children()
    }

    /// The head atom of a list (first child's text if it's an Atom).
    pub fn head_atom(&self) -> Option<&str> {
        self.children()
            .and_then(|cs| cs.first())
            .and_then(|c| c.as_atom())
    }
}

// ── Functor (map) ──────────────────────────────────────────────────

impl<A> Doc<A> {
    /// Transform every annotation in the tree, preserving structure and layout.
    pub fn map<B>(self, f: &impl Fn(A) -> B) -> Doc<B> {
        Doc {
            ann: f(self.ann),
            node: self.node.map(|c| c.map(f)),
            layout: self.layout,
            dimmed: self.dimmed,
        }
    }
}

// ── Catamorphism (fold) ────────────────────────────────────────────

impl<A> Doc<A> {
    /// Bottom-up fold. Children are reduced first, then the algebra
    /// receives the shape (with reduced children) and the annotation.
    pub fn fold<B>(&self, alg: &impl Fn(DocF<B>, &A) -> B) -> B {
        let reduced = self.node.map_ref(|child| child.fold(alg));
        alg(reduced, &self.ann)
    }
}

