// ── Property-based tests ────────────────────────────────────────────

#[cfg(test)]
mod prop_tests {
    use super::*;
    use proptest::prelude::*;

    fn arb_decision() -> impl Strategy<Value = Decision> {
        prop_oneof![
            Just(Decision::Allow),
            Just(Decision::Ask),
            Just(Decision::Deny),
        ]
    }

    // Expr strategy: recursive tree of Literal, Wildcard, And, Or, Not.
    // Skips Regex (hard to generate valid patterns) and Cond (has effects).
    fn arb_expr() -> impl Strategy<Value = Expr> {
        let leaf = prop_oneof!["[a-z]{1,8}".prop_map(Expr::Literal), Just(Expr::Wildcard),];
        leaf.prop_recursive(4, 16, 4, |inner| {
            prop_oneof![
                prop::collection::vec(inner.clone(), 1..4).prop_map(Expr::And),
                prop::collection::vec(inner.clone(), 1..4).prop_map(Expr::Or),
                inner.prop_map(|e| Expr::Not(Box::new(e))),
            ]
        })
    }

    // ── Decision lattice ────────────────────────────────────────────

    proptest! {
        #[test]
        fn decision_most_restrictive_is_commutative(a in arb_decision(), b in arb_decision()) {
            prop_assert_eq!(a.most_restrictive(b), b.most_restrictive(a));
        }

        #[test]
        fn decision_most_restrictive_is_associative(
            a in arb_decision(), b in arb_decision(), c in arb_decision()
        ) {
            prop_assert_eq!(
                a.most_restrictive(b).most_restrictive(c),
                a.most_restrictive(b.most_restrictive(c))
            );
        }

        #[test]
        fn decision_most_restrictive_is_idempotent(a in arb_decision()) {
            prop_assert_eq!(a.most_restrictive(a), a);
        }

        #[test]
        fn decision_deny_is_absorbing(a in arb_decision()) {
            prop_assert_eq!(a.most_restrictive(Decision::Deny), Decision::Deny);
        }

        #[test]
        fn decision_allow_is_identity(a in arb_decision()) {
            prop_assert_eq!(a.most_restrictive(Decision::Allow), a);
        }

        #[test]
        fn decision_most_restrictive_is_at_least_as_restrictive(
            a in arb_decision(), b in arb_decision()
        ) {
            let result = a.most_restrictive(b);
            prop_assert!(result >= a);
            prop_assert!(result >= b);
        }
    }

    // ── Expr boolean algebra ────────────────────────────────────────

    proptest! {
        #[test]
        fn expr_wildcard_matches_anything(s in "[a-z]{0,20}") {
            prop_assert!(Expr::Wildcard.is_match(&s));
        }

        #[test]
        fn expr_literal_matches_only_itself(s in "[a-z]{1,10}") {
            let e = Expr::Literal(s.clone());
            prop_assert!(e.is_match(&s));
        }

        #[test]
        fn expr_literal_rejects_different(a in "[a-z]{1,5}", b in "[a-z]{1,5}") {
            prop_assume!(a != b);
            prop_assert!(!Expr::Literal(a).is_match(&b));
        }

        #[test]
        fn expr_double_negation(e in arb_expr(), s in "[a-z]{1,10}") {
            let double_neg = Expr::Not(Box::new(Expr::Not(Box::new(e.clone()))));
            prop_assert_eq!(e.is_match(&s), double_neg.is_match(&s));
        }

        #[test]
        fn expr_and_is_commutative(a in arb_expr(), b in arb_expr(), s in "[a-z]{1,10}") {
            let ab = Expr::And(vec![a.clone(), b.clone()]);
            let ba = Expr::And(vec![b, a]);
            prop_assert_eq!(ab.is_match(&s), ba.is_match(&s));
        }

        #[test]
        fn expr_or_is_commutative(a in arb_expr(), b in arb_expr(), s in "[a-z]{1,10}") {
            let ab = Expr::Or(vec![a.clone(), b.clone()]);
            let ba = Expr::Or(vec![b, a]);
            prop_assert_eq!(ab.is_match(&s), ba.is_match(&s));
        }

        #[test]
        fn expr_de_morgan_not_and(a in arb_expr(), b in arb_expr(), s in "[a-z]{1,10}") {
            // !(a && b) == (!a || !b)
            let lhs = Expr::Not(Box::new(Expr::And(vec![a.clone(), b.clone()])));
            let rhs = Expr::Or(vec![
                Expr::Not(Box::new(a)),
                Expr::Not(Box::new(b)),
            ]);
            prop_assert_eq!(lhs.is_match(&s), rhs.is_match(&s));
        }

        #[test]
        fn expr_de_morgan_not_or(a in arb_expr(), b in arb_expr(), s in "[a-z]{1,10}") {
            // !(a || b) == (!a && !b)
            let lhs = Expr::Not(Box::new(Expr::Or(vec![a.clone(), b.clone()])));
            let rhs = Expr::And(vec![
                Expr::Not(Box::new(a)),
                Expr::Not(Box::new(b)),
            ]);
            prop_assert_eq!(lhs.is_match(&s), rhs.is_match(&s));
        }

        #[test]
        fn expr_and_with_wildcard_is_identity(e in arb_expr(), s in "[a-z]{1,10}") {
            let ew = Expr::And(vec![e.clone(), Expr::Wildcard]);
            prop_assert_eq!(e.is_match(&s), ew.is_match(&s));
        }

        #[test]
        fn expr_or_with_wildcard_always_matches(e in arb_expr(), s in "[a-z]{1,10}") {
            let ew = Expr::Or(vec![e, Expr::Wildcard]);
            prop_assert!(ew.is_match(&s));
        }
    }
}

// Core AST types for the unified rule DSL.

use crate::span::Span;
use crate::types::Decision;
use crate::v2::pattern::{ArgPattern, CommandPattern};
use crate::v2::predicate::Predicate;

/// A value with source span tracking.
#[derive(Debug, Clone)]
pub struct Spanned<T> {
    pub value: T,
    pub span: Span,
}

impl<T> Spanned<T> {
    /// Create a new spanned value.
    pub fn new(value: T, span: Span) -> Self {
        Self { value, span }
    }

    /// Map over the inner value, preserving the span.
    pub fn map<U, F: FnOnce(T) -> U>(self, f: F) -> Spanned<U> {
        Spanned {
            value: f(self.value),
            span: self.span,
        }
    }
}

/// Authorization effect: a decision with optional message and recursive evaluation.
#[derive(Debug, Clone)]
pub enum Effect {
    /// Allow the command.
    /// Syntax: `(effect :allow)` or `(effect :allow "reason")`
    Allow(Option<String>),

    /// Ask for confirmation.
    /// Syntax: `(effect :ask)` or `(effect :ask "reason")`
    Ask(Option<String>),

    /// Deny the command.
    /// Syntax: `(effect :deny)` or `(effect :deny "reason")`
    Deny(Option<String>),

    /// Recursively evaluate an inner command.
    /// Syntax: `(may-i PATTERN)`
    Evaluate(ArgPattern),

    /// Branch on predicates: first matching branch wins.
    /// Syntax: `(case [(PREDICATE EFFECT) ...] [ELSE-EFFECT])`
    Case {
        branches: Vec<(Spanned<Predicate>, Spanned<Effect>)>,
        fallback: Option<Box<Spanned<Effect>>>,
    },

    /// Conditional effect: applies only when predicate is true.
    /// Sugar form preserved for trace output.
    /// Syntax: `(when PREDICATE EFFECT)`
    When {
        predicate: Spanned<Predicate>,
        effect: Box<Spanned<Effect>>,
    },

    /// Conditional effect: applies only when predicate is false.
    /// Sugar form preserved for trace output.
    /// Syntax: `(unless PREDICATE EFFECT)`
    Unless {
        predicate: Spanned<Predicate>,
        effect: Box<Spanned<Effect>>,
    },

    /// Conditional effect with both then and else branches.
    /// Sugar form preserved for trace output.
    /// Syntax: `(if PREDICATE THEN-EFFECT [ELSE-EFFECT])`
    If {
        predicate: Spanned<Predicate>,
        then_effect: Box<Spanned<Effect>>,
        else_effect: Option<Box<Spanned<Effect>>>,
    },
}

impl Effect {
    /// Create an allow effect.
    pub fn allow(reason: Option<String>) -> Self {
        Effect::Allow(reason)
    }

    /// Create an ask effect.
    pub fn ask(reason: Option<String>) -> Self {
        Effect::Ask(reason)
    }

    /// Create a deny effect.
    pub fn deny(reason: Option<String>) -> Self {
        Effect::Deny(reason)
    }

    /// Create a recursive evaluation effect.
    pub fn evaluate(pattern: ArgPattern) -> Self {
        Effect::Evaluate(pattern)
    }

    /// Get the terminal decision if this is a terminal effect.
    pub fn terminal_decision(&self) -> Option<Decision> {
        match self {
            Effect::Allow(_) => Some(Decision::Allow),
            Effect::Ask(_) => Some(Decision::Ask),
            Effect::Deny(_) => Some(Decision::Deny),
            _ => None,
        }
    }

    /// Check if this is a terminal effect (Allow, Ask, or Deny).
    pub fn is_terminal(&self) -> bool {
        matches!(self, Effect::Allow(_) | Effect::Ask(_) | Effect::Deny(_))
    }

    /// Check if this is a sugar form (When, Unless, If).
    pub fn is_sugar(&self) -> bool {
        matches!(
            self,
            Effect::When { .. } | Effect::Unless { .. } | Effect::If { .. }
        )
    }
}

/// A named predicate definition.
/// Syntax: `(define NAME PREDICATE)`
#[derive(Debug, Clone)]
pub struct Define {
    /// The name of the predicate.
    pub name: String,

    /// The predicate body.
    pub predicate: Spanned<Predicate>,

    /// Source span for error reporting.
    pub span: Span,
}

impl Define {
    /// Create a new named predicate definition.
    pub fn new(name: impl Into<String>, predicate: Spanned<Predicate>, span: Span) -> Self {
        Self {
            name: name.into(),
            predicate,
            span,
        }
    }
}

/// An authorization rule.
/// Syntax: `(rule COMMAND-PREDICATE PREDICATE* EFFECT)`
#[derive(Debug, Clone)]
pub struct Rule {
    /// The command pattern (position 1 of the rule).
    pub command: Spanned<CommandPattern>,

    /// Additional predicates that must all match.
    pub predicates: Vec<Spanned<Predicate>>,

    /// The effect to apply when predicates match.
    pub effect: Spanned<Effect>,

    /// Source span for error reporting.
    pub span: Span,
}

impl Rule {
    /// Create a new rule.
    pub fn new(
        command: Spanned<CommandPattern>,
        predicates: Vec<Spanned<Predicate>>,
        effect: Spanned<Effect>,
        span: Span,
    ) -> Self {
        Self {
            command,
            predicates,
            effect,
            span,
        }
    }
}

/// Top-level configuration for the unified rule DSL.
#[derive(Debug, Clone, Default)]
pub struct Config {
    /// Named predicate definitions.
    pub defines: Vec<Define>,

    /// Authorization rules.
    pub rules: Vec<Rule>,

