// Variable safety tracking for AST analysis.

use may_i_shell_parser::{Command, SimpleCommand, Word, WordPart};

/// The safety state of a shell variable during AST analysis.
#[derive(Debug, Clone, PartialEq)]
pub enum VarState {
    /// Resolvable to a known literal value.
    Known(String),
    /// Safe but value unknown at analysis time (e.g. loop variable, read input).
    Opaque,
    /// Assigned from an unknown or untrusted source.
    Unsafe,
}

/// Tracks variable safety state through AST evaluation.
#[derive(Debug, Clone)]
pub struct VarEnv {
    vars: std::collections::HashMap<String, VarState>,
    fns: std::collections::HashMap<String, Command>,
}

impl VarEnv {
    /// Seed from all process environment variables.
    /// Every env var is `Safe(Some(value))` at startup.
    pub fn from_process_env() -> Self {
        let mut vars = std::collections::HashMap::new();
        for (key, val) in std::env::vars() {
            vars.insert(key, VarState::Known(val));
        }
        VarEnv {
            vars,
            fns: std::collections::HashMap::new(),
        }
    }

    pub fn get(&self, name: &str) -> Option<&VarState> {
        self.vars.get(name)
    }

    pub fn set(&mut self, name: String, state: VarState) {
        self.vars.insert(name, state);
    }

    /// Merge a list of branch environments that all forked from `pre`.
    /// For each variable across all branches:
    /// - Same `Safe(Some(v))` in all → keep `Safe(Some(v))`
    /// - `Safe` in all but different values → `Safe(None)` (opaque)
    /// - `Unsafe` in any branch → `Unsafe`
    /// - Absent in some branches → use `pre`'s value for those branches
    pub fn merge_branches(pre: &VarEnv, branches: &[VarEnv]) -> VarEnv {
        if branches.is_empty() {
            return pre.clone();
        }

        let mut all_keys: std::collections::HashSet<&String> = std::collections::HashSet::new();
        for branch in branches {
            all_keys.extend(branch.vars.keys());
        }
        all_keys.extend(pre.vars.keys());

        let mut result = std::collections::HashMap::new();

        for key in all_keys {
            let mut any_absent = false;
            let mut states: Vec<&VarState> = Vec::new();
            for branch in branches {
                if let Some(s) = branch.vars.get(key).or_else(|| pre.vars.get(key)) {
                    states.push(s);
                } else {
                    any_absent = true;
                }
            }

            if states.is_empty() && !any_absent {
                continue;
            }

            if any_absent || states.iter().any(|s| matches!(s, VarState::Unsafe)) {
                result.insert(key.clone(), VarState::Unsafe);
                continue;
            }

            let first = &states[0];
            if states.iter().all(|s| *s == *first) {
                result.insert(key.clone(), (*first).clone());
            } else {
                result.insert(key.clone(), VarState::Opaque);
            }
        }

        let mut fns = pre.fns.clone();
        for branch in branches {
            for (name, body) in &branch.fns {
                fns.insert(name.clone(), body.clone());
            }
        }

        VarEnv { vars: result, fns }
    }

    /// Check if a variable is safe (regardless of whether its value is known).
    pub fn is_safe(&self, name: &str) -> bool {
        matches!(self.get(name), Some(VarState::Known(_) | VarState::Opaque))
    }

    /// Store a function definition.
    pub fn set_fn(&mut self, name: String, body: Command) {
        self.fns.insert(name, body);
    }

    /// Retrieve a function definition.
    pub fn get_fn(&self, name: &str) -> Option<&Command> {
        self.fns.get(name)
    }
}

// ── VarEnv-based resolution helpers ─────────────────────────────────
// These were originally in parser/ast.rs but depend on VarEnv, so they
// live here to avoid a circular dependency.

/// Resolve variables using VarEnv: Safe(Some) → Literal, Safe(None) → Opaque, absent → keep.
pub fn resolve_parts_with_var_env(parts: &[WordPart], env: &VarEnv) -> Vec<WordPart> {
    parts
        .iter()
        .map(|part| match part {
            WordPart::Parameter(name) | WordPart::ParameterExpansion(name) => match env.get(name) {
                Some(VarState::Known(val)) => WordPart::Literal(val.clone()),
                Some(VarState::Opaque) => WordPart::Opaque(format!("${name}")),
                Some(VarState::Unsafe) | None => part.clone(),
            },
            WordPart::ParameterExpansionOp { name, op } => match env.get(name) {
                Some(VarState::Known(val)) => {
                    let mut map = std::collections::HashMap::new();
                    map.insert(name.clone(), val.clone());
                    may_i_shell_parser::resolve_param_op(name, op, &map)
                }
                Some(VarState::Opaque) => WordPart::Opaque(format!("${{{name}...}}")),
                Some(VarState::Unsafe) | None => part.clone(),
            },
            WordPart::DoubleQuoted(inner) => {
                WordPart::DoubleQuoted(resolve_parts_with_var_env(inner, env))
            }
            _ => part.clone(),
        })
        .collect()
}

/// Resolve a Word using VarEnv. Safe+resolvable variables become Literal,
/// safe+opaque variables become Opaque, unsafe/unknown variables stay as Parameter.
pub fn resolve_word_with_var_env(word: &Word, env: &VarEnv) -> Word {
    Word {
        parts: resolve_parts_with_var_env(&word.parts, env),
    }
}

/// Resolve a SimpleCommand using VarEnv in all words, assignment values,
/// and redirect file targets.
pub fn resolve_simple_command_with_var_env(sc: &SimpleCommand, env: &VarEnv) -> SimpleCommand {
    sc.map_words(|w| resolve_word_with_var_env(w, env))
}

// Visitor that detects code-execution constructs (source, eval, bash -c)
// and either returns Ask or requests recursion into the inner command.

use super::{CommandVisitor, MAX_EVAL_DEPTH, VisitOutcome, VisitorContext};
use may_i_core::{Decision, EvalResult};
use may_i_shell_parser::{self as parser, SimpleCommand};

/// Detects `source`/`.`, opaque command names, `eval`, and `bash/sh/zsh -c`.
///
/// - `source`/`.`: always Ask (file contents unknown).
/// - Opaque command name: Ask (can't determine what runs).
/// - `eval`: concatenate literal args and Recurse, or Ask if opaque.
/// - `bash -c` / `sh -c` / `zsh -c`: Recurse into the `-c` argument.
pub(crate) struct CodeExecutionVisitor;

impl CommandVisitor for CodeExecutionVisitor {
    fn visit_simple_command(&self, ctx: &VisitorContext, resolved: &SimpleCommand) -> VisitOutcome {
        // Opaque variable as command name (must check before nonempty_command_name
        // since opaque commands resolve to an empty name)
        if resolved.words.first().is_some_and(|w| w.has_opaque_parts()) {
            return VisitOutcome::Terminal {
                result: EvalResult::new(
                    Decision::Ask,
                    Some("Variable used as command name: cannot determine what runs".into()),
                ),
                env: ctx.env.clone(),
            };
        }

        let cmd_name = match resolved.nonempty_command_name() {
            Some(name) => name,
            None => return VisitOutcome::Continue,
        };

        // source / . — always Ask
        if cmd_name == "source" || cmd_name == "." {
            return VisitOutcome::Terminal {
                result: EvalResult::new(
                    Decision::Ask,
                    Some(format!(
                        "Cannot statically analyse `{cmd_name}`: sourced file contents are unknown"
                    )),
                ),
                env: ctx.env.clone(),
            };
        }

        // eval
        if cmd_name == "eval" && ctx.depth < MAX_EVAL_DEPTH {
            return self.visit_eval(ctx, resolved);
        }

        // bash -c / sh -c / zsh -c
        if matches!(cmd_name, "bash" | "sh" | "zsh")
            && ctx.depth < MAX_EVAL_DEPTH
            && let Some(outcome) = self.visit_shell_dash_c(ctx, resolved)
        {
            return outcome;
        }

        VisitOutcome::Continue
    }
}

impl CodeExecutionVisitor {
    fn visit_eval(&self, ctx: &VisitorContext, resolved: &SimpleCommand) -> VisitOutcome {
        let args = resolved.args();

        if args.is_empty() {
            return VisitOutcome::Terminal {
                result: EvalResult::new(Decision::Allow, None),
                env: ctx.env.clone(),
            };
        }

        // Opaque args: safe but unknown value
        if args.iter().any(|a| a.has_opaque_parts()) {
            return VisitOutcome::Terminal {
                result: EvalResult::new(
                    Decision::Ask,
                    Some("Cannot determine eval'd command: argument value is unknown".into()),
                ),
                env: ctx.env.clone(),
            };
        }

        // All args are literal — concatenate and recurse
        let eval_str: String = args
            .iter()
            .map(|a| a.to_str())
            .collect::<Vec<_>>()
            .join(" ");
        let inner_ast = parser::parse(&eval_str);
        VisitOutcome::Recurse {
            command: inner_ast,
            env: ctx.env.clone(),
            context: ctx.context.clone(),
        }
    }

    fn visit_shell_dash_c(
        &self,
        ctx: &VisitorContext,
        resolved: &SimpleCommand,
    ) -> Option<VisitOutcome> {
        let args = resolved.args();

        let mut found_c = false;
        let mut cmd_arg = None;
        for arg in args {
            let s = arg.to_str();
            if found_c {
                cmd_arg = Some(arg);
                break;
            }
            if s == "-c" {
                found_c = true;
            }
        }

        if !found_c {
            return None;
        }

        let cmd_arg = cmd_arg?;

        if cmd_arg.has_dynamic_parts() {
            return None; // fall through to rule matching
        }

        if cmd_arg.has_opaque_parts() {
            return Some(VisitOutcome::Terminal {
                result: EvalResult::new(
                    Decision::Ask,
                    Some(format!(
                        "Cannot determine `{} -c` command: argument value is unknown",
                        resolved.command_name().unwrap_or("sh"),
                    )),
                ),
                env: ctx.env.clone(),
            });
        }

        let cmd_str = cmd_arg.to_str();
        let inner_ast = parser::parse(&cmd_str);
        Some(VisitOutcome::Recurse {
            command: inner_ast,
            env: ctx.env.clone(),
            context: ctx.context.clone(),
        })
    }
}

// Visitor that detects unresolvable dynamic parts in a resolved command.

use super::{CommandVisitor, VisitOutcome, VisitorContext, dynamic_ask};
use may_i_shell_parser::SimpleCommand;

/// Returns `Ask` when a resolved command still contains dynamic parts
/// (unsafe variables, command substitutions, etc.) that prevent static analysis.
pub(crate) struct DynamicPartsVisitor;

impl CommandVisitor for DynamicPartsVisitor {
    fn visit_simple_command(&self, ctx: &VisitorContext, resolved: &SimpleCommand) -> VisitOutcome {
        let mut dynamic = Vec::new();
        for word in &resolved.words {
            dynamic.extend(word.dynamic_parts());
        }
        for assignment in &resolved.assignments {
            dynamic.extend(assignment.value.dynamic_parts());
        }
        for redir in &resolved.redirections {
            if let may_i_shell_parser::RedirectionTarget::File(w) = &redir.target {
                dynamic.extend(w.dynamic_parts());
            }
        }

        if dynamic.is_empty() {
            return VisitOutcome::Continue;
        }

        let cmd_label = resolved.command_name().unwrap_or("<unknown>");
        VisitOutcome::Terminal {
            result: dynamic_ask(&dynamic, &format!("Command `{cmd_label}` contains")),
            env: ctx.env.clone(),
        }
    }
}

// Visitor that handles shell function calls by inlining the function body.

use super::{CommandVisitor, MAX_EVAL_DEPTH, VisitOutcome, VisitorContext};
use crate::var_env::VarState;
use may_i_shell_parser::SimpleCommand;

/// When the command name matches a previously defined function, set up
/// positional parameters and recurse into the function body.
pub(crate) struct FunctionCallVisitor;

impl CommandVisitor for FunctionCallVisitor {
    fn visit_simple_command(&self, ctx: &VisitorContext, resolved: &SimpleCommand) -> VisitOutcome {
        let cmd_name = match resolved.nonempty_command_name() {
            Some(name) => name,
            None => return VisitOutcome::Continue,
        };

        if ctx.depth >= MAX_EVAL_DEPTH {
            return VisitOutcome::Continue;
        }

        let body = match ctx.env.get_fn(cmd_name) {
            Some(body) => body.clone(),
            None => return VisitOutcome::Continue,
        };

        // Set up positional parameters ($1, $2, ...) from the call arguments
        let mut fn_env = ctx.env.clone();
        for (i, arg) in resolved.args().iter().enumerate() {
            let state = if arg.is_literal() {
                VarState::Known(arg.to_str())
            } else if arg.has_opaque_parts() {
                VarState::Opaque
            } else {
                VarState::Unsafe
            };
            fn_env.set(format!("{}", i + 1), state);
        }

        VisitOutcome::Recurse {
            command: body,
            env: fn_env,
            context: ctx.context.clone(),
        }
    }
}

// Visitor trait and concrete visitor implementations for the engine.

pub(crate) mod code_execution;
pub(crate) mod dynamic_parts;
pub(crate) mod function_call;
pub(crate) mod read_builtin;
pub(crate) mod rule_match;
pub(crate) mod wrapper_unwrap;

use crate::var_env::VarEnv;
use may_i_core::{Config, ContextFacts, Decision, EvalResult};
use may_i_shell_parser::{Command, SimpleCommand};

/// Maximum recursion depth for command substitution / eval / bash -c evaluation.
pub(crate) const MAX_EVAL_DEPTH: usize = 10;

/// Build an Ask result for unresolvable dynamic values.
/// `context` is a prefix like "Cannot statically analyse" or
/// "Command `foo` contains".
pub(crate) fn dynamic_ask(dynamic: &[String], context: &str) -> EvalResult {
    let mut seen = std::collections::HashSet::new();
    let parts: Vec<&str> = dynamic
        .iter()
        .filter(|p| seen.insert(p.as_str()))
        .map(|p| p.as_str())
        .collect();
    EvalResult::new(
        Decision::Ask,
        Some(format!(
            "{context} dynamic value{} that cannot be statically analysed: {}",
            if parts.len() == 1 { "" } else { "s" },
            parts.join(", "),
        )),
    )
}

/// Outcome of a visitor inspecting a resolved simple command.
pub(crate) enum VisitOutcome {
    /// Terminal: return this result, skip remaining visitors.
    /// The `env` may differ from the input (e.g. `read` builtin updates variables).
    Terminal { result: EvalResult, env: VarEnv },
    /// This visitor doesn't handle the command; try the next one.
    Continue,
    /// Re-walk a different command (e.g. after unwrapping `eval`, `bash -c`,
    /// or wrapper commands). The walker will recursively walk the new command.
    Recurse {
        command: Command,
        env: VarEnv,
        context: ContextFacts,
    },
}

/// Context passed to visitors, providing read access to walker state.
pub(crate) struct VisitorContext<'a> {
    pub config: &'a Config,
    pub context: &'a ContextFacts,
    pub env: &'a VarEnv,
    pub depth: usize,
}

/// Trait for leaf-level command behaviors.
///
/// Each visitor inspects a fully-resolved `SimpleCommand` and returns a
/// `VisitOutcome` indicating whether it handled the command, wants to
/// pass, or wants the walker to recurse into a different command.
///
/// The walker calls visitors in order; the first non-`Continue` outcome wins.
pub(crate) trait CommandVisitor {
    /// Inspect a resolved simple command.
    ///
    /// Called after variable resolution and command-substitution resolution,
    /// so all resolvable parts are already literals or opaque.
    fn visit_simple_command(&self, ctx: &VisitorContext, resolved: &SimpleCommand) -> VisitOutcome {
        let _ = (ctx, resolved);
        VisitOutcome::Continue
    }
}

// Visitor that handles `read`, `readarray`, and `mapfile` builtins
// by marking the target variables as safe in the environment.

use super::{CommandVisitor, VisitOutcome, VisitorContext};
use crate::var_env::VarState;
use may_i_core::{Decision, EvalResult};
use may_i_shell_parser::{self as parser, SimpleCommand};

/// Detects `read`/`readarray`/`mapfile` and updates the variable
/// environment to mark target variables as safe (value unknown at
/// analysis time, but user-controlled input is considered safe).
pub(crate) struct ReadBuiltinVisitor;

impl CommandVisitor for ReadBuiltinVisitor {
    fn visit_simple_command(&self, ctx: &VisitorContext, resolved: &SimpleCommand) -> VisitOutcome {
        let cmd_name = match resolved.command_name() {
            Some(name) if matches!(name, "read" | "readarray" | "mapfile") => name,
            _ => return VisitOutcome::Continue,
        };

        // Flags that take an argument (the next token is consumed)
        let flags_with_arg: &[&str] = match cmd_name {
            "read" => &["-d", "-n", "-N", "-p", "-t", "-u"],
            "readarray" | "mapfile" => &["-d", "-n", "-O", "-t", "-u", "-C", "-c"],
            _ => &[],
        };

        // Extract variable names from args (skip flags and their values)
        let args = resolved.args();
        let mut var_names = Vec::new();
        let mut skip_value = false;
        for arg in args {
            let s = arg.to_str();
            if skip_value {
                skip_value = false;
                continue;
            }
            if s.starts_with('-') && s.len() > 1 {
                skip_value = flags_with_arg.iter().any(|f| *f == s);
                continue;
            }
            var_names.push(s);
        }

        // Check for herestring with literal value
        let herestring_val = resolved.redirections.iter().find_map(|r| {
            if matches!(r.kind, parser::RedirectionKind::Herestring)
                && let parser::RedirectionTarget::File(w) = &r.target
                && w.is_literal()
            {
                return Some(w.to_str());
            }
            None
        });

        // Default variable name for `read` is REPLY
        if var_names.is_empty() && cmd_name == "read" {
            var_names.push("REPLY".to_string());
        }

        // Set variables: if herestring with known value and single var, use it;
        // otherwise Safe(None) (user-controlled input is safe but unknown)
        let mut new_env = ctx.env.clone();
        for (i, name) in var_names.iter().enumerate() {
            let state = if var_names.len() == 1 && i == 0 {
                match &herestring_val {
                    Some(val) => VarState::Known(val.clone()),
                    None => VarState::Opaque,
                }
            } else {
                VarState::Opaque
            };
            new_env.set(name.clone(), state);
        }

        VisitOutcome::Terminal {
            result: EvalResult::new(Decision::Allow, None),
            env: new_env,
        }
    }
}

// Visitor that matches resolved commands against config rules.
// Terminal visitor: always returns Terminal (never Continue).

use super::{CommandVisitor, VisitOutcome, VisitorContext};
use crate::annotate::annotate_rule;
use crate::matcher::*;
use may_i_core::{Config, ContextFacts, Decision, Effect, EvalResult, TraceEntry};
use may_i_shell_parser::SimpleCommand;

/// Terminal visitor: matches the resolved command against config rules.
/// Always returns Terminal (never Continue).
pub(crate) struct RuleMatchVisitor;

impl CommandVisitor for RuleMatchVisitor {
    fn visit_simple_command(&self, ctx: &VisitorContext, resolved: &SimpleCommand) -> VisitOutcome {
        let result = match_against_rules(resolved, ctx.config, ctx.context);
        VisitOutcome::Terminal {
            result,
            env: ctx.env.clone(),
        }
    }
}

/// Pure rule-matching logic: expand flags, iterate rules, return first match.
pub(crate) fn match_against_rules(
    resolved: &SimpleCommand,
    config: &Config,
    context: &ContextFacts,
) -> EvalResult {
    let cmd_name = match resolved.nonempty_command_name() {
        Some(name) => name,
        None => {
            return EvalResult::new(Decision::Ask, Some("Unknown command".into()));
        }
    };

    // Expand flags: -abc → -a -b -c (R8)
    let expanded_args = expand_flags(resolved.args());

    // Evaluate against rules: deny rules first, then first match
    let mut first_match: Option<EvalResult> = None;
    let mut trace = Vec::new();
    let mut had_command_match = false;

    for rule in &config.rules {
        if !command_matches(cmd_name, &rule.command) {
            continue;
        }

        had_command_match = true;
        let line_num = config
            .source_info
            .as_ref()
            .map(|si| si.line_of(rule.source_span));
        let (doc, effect) = annotate_rule(rule, cmd_name, &expanded_args, context);
        trace.push(TraceEntry::Rule {
            doc: Box::new(doc),
            line: line_num,
        });

        let effect = match effect {
            Some(eff) => eff,
            None => continue, // args didn't match
        };

        let Effect { decision, reason } = effect;
        let mut result = EvalResult::new(decision, reason);

        if decision == Decision::Deny {
            result.trace = trace;
            return result;
        }

        if first_match.is_none() {
            result.trace = trace.clone();
            first_match = Some(result);
        }
    }

    first_match.unwrap_or_else(|| {
        let reason = if had_command_match {
            format!(
                "Rules for `{cmd_name}` exist but context or arguments did not match any patterns"
            )
        } else {
            format!("No rule for command `{cmd_name}`")
        };
        trace.push(TraceEntry::DefaultAsk {
            reason: reason.clone(),
        });
        let mut result = EvalResult::new(Decision::Ask, Some(reason));
        result.trace = trace;
        result
    })
}

// Visitor that peels known wrapper commands (e.g. sudo, env) and
// recurses into the inner command.

use super::{CommandVisitor, VisitOutcome, VisitorContext};
use crate::matcher::unwrap_wrapper;
use may_i_core::{Decision, EvalResult};
use may_i_shell_parser::{self as parser, Command, SimpleCommand};

/// Peels known wrapper commands and recurses into the inner command.
/// If the inner command is a single word containing spaces, it is
/// parsed as a full AST.
pub(crate) struct WrapperUnwrapVisitor;

impl CommandVisitor for WrapperUnwrapVisitor {
    fn visit_simple_command(&self, ctx: &VisitorContext, resolved: &SimpleCommand) -> VisitOutcome {
        let cmd_name = match resolved.nonempty_command_name() {
            Some(name) => name,
            None => return VisitOutcome::Continue,
        };

        let inner = match unwrap_wrapper(resolved, ctx.config) {
            Some(inner) => inner,
            None => return VisitOutcome::Continue,
        };
        let next_context = ctx.context.merge(&inner.facts);

        // Single-word inner command may contain spaces (e.g. from variable expansion)
        if inner.command.words.len() == 1 {
            let word = &inner.command.words[0];
            if word.has_opaque_parts() {
                return VisitOutcome::Terminal {
                    result: EvalResult::new(
                        Decision::Ask,
                        Some(format!(
                            "Cannot determine inner command for `{cmd_name}`: \
                             argument value is unknown"
                        )),
                    ),
                    env: ctx.env.clone(),
                };
            }
            let s = word.to_str();
            if s.contains(' ') {
                let inner_ast = parser::parse(&s);
                return VisitOutcome::Recurse {
                    command: inner_ast,
                    env: ctx.env.clone(),
                    context: next_context,
                };
            }
        }

        VisitOutcome::Recurse {
            command: Command::Simple(inner.command),
            env: ctx.env.clone(),
            context: next_context,
        }
    }
}

// S-expression pretty-printer with configurable width and syntax coloring.
//
// The core Doc/DocF types live in `may-i-core::doc` and are re-exported here
// for convenience. This crate provides rendering (pretty-printing, colorization)
// and s-expression string parsing.

use colored::Colorize;

pub use may_i_core::{Doc, DocF, LayoutHint};

// ── from_sexpr (test-only) ─────────────────────────────────────────

#[cfg(test)]
fn doc_from_sexpr(sexpr: &may_i_sexpr::Sexpr) -> Doc {
    match sexpr {
        may_i_sexpr::Sexpr::Atom(s, _) => {
            let text = if may_i_sexpr::needs_quoting(s) {
                may_i_sexpr::quote_atom(s)
            } else {
                s.clone()
            };
            Doc::atom(text)
        }
        may_i_sexpr::Sexpr::List(items, _) | may_i_sexpr::Sexpr::Vector(items, _) => {
            Doc::list(items.iter().map(doc_from_sexpr).collect())
        }
    }
}

// ── S-expression string parser ──────────────────────────────────────

/// Parse an s-expression string (e.g. `(command "curl")`) into a Doc tree.
pub fn parse_sexpr(input: &str) -> Doc {
    let tokens = tokenize(input);
    if tokens.is_empty() {
        return Doc::atom("");
    }
    let (doc, _) = parse_tokens(&tokens, 0);
    doc
}

fn tokenize(input: &str) -> Vec<&str> {
    let mut tokens = Vec::new();
    let bytes = input.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        match bytes[i] {
            b' ' | b'\t' | b'\n' => {
                i += 1;
            }
            b'(' => {
                tokens.push(&input[i..i + 1]);
                i += 1;
            }
            b')' => {
                tokens.push(&input[i..i + 1]);
                i += 1;
            }
            b'"' => {
                let start = i;
                i += 1;
                while i < bytes.len() && bytes[i] != b'"' {
                    if bytes[i] == b'\\' {
                        i += 1;
                    }
                    i += 1;
                }
                if i < bytes.len() {
                    i += 1;
                }
                tokens.push(&input[start..i]);
            }
            b'#' if i + 1 < bytes.len() && bytes[i + 1] == b'"' => {
                let start = i;
                i += 2;
                while i < bytes.len() && bytes[i] != b'"' {
                    if bytes[i] == b'\\' {
                        i += 1;
                    }
                    i += 1;
                }
                if i < bytes.len() {
                    i += 1;
                }
                tokens.push(&input[start..i]);
            }
            _ => {
                let start = i;
                while i < bytes.len() && !matches!(bytes[i], b' ' | b'\t' | b'\n' | b'(' | b')') {
                    i += 1;
                }
                tokens.push(&input[start..i]);
            }
        }
    }
    tokens
}

fn parse_tokens(tokens: &[&str], pos: usize) -> (Doc, usize) {
    if pos >= tokens.len() {
        return (Doc::atom(""), pos);
    }
    if tokens[pos] == "(" {
        let mut children = Vec::new();
        let mut i = pos + 1;
        while i < tokens.len() && tokens[i] != ")" {
            let (child, next) = parse_tokens(tokens, i);
            children.push(child);
            i = next;
        }
        if i < tokens.len() {
            i += 1;
        } // skip )
        (Doc::list(children), i)
    } else {
        (Doc::atom(tokens[pos]), pos + 1)
    }
}

// ── Doc transforms ─────────────────────────────────────────────────

/// Truncate long lists in a Doc tree, keeping the first `keep`
/// and last 1 elements with an `…` ellipsis in between.
pub fn truncate_long_lists(doc: &Doc, keep: usize) -> Doc {
    match &doc.node {
        DocF::Atom(_) => doc.clone(),
        DocF::List(children) => {
            let children: Vec<Doc> = children
                .iter()
                .map(|c| truncate_long_lists(c, keep))
                .collect();
            let has_head = children.first().is_some_and(|c| c.as_atom().is_some());
            if has_head && children.len() > keep + 2 {
                let mut truncated = Vec::with_capacity(keep + 3);
                truncated.push(children[0].clone());
                truncated.extend(children[1..=keep].iter().cloned());
                truncated.push(Doc::atom("…"));
                truncated.push(children.last().unwrap().clone());
                Doc::list(truncated)
            } else {
                Doc {
                    ann: (),
                    node: DocF::List(children),
                    layout: doc.layout,
                    dimmed: false,
                }
            }
        }
        DocF::Vector(children) => Doc {
            ann: (),
            node: DocF::Vector(
                children
                    .iter()
                    .map(|c| truncate_long_lists(c, keep))
                    .collect(),
            ),
            layout: doc.layout,
            dimmed: false,
        },
    }
}

// ── Atom classification ─────────────────────────────────────────────

const SPECIAL_FORMS: &[&str] = &[
    "rule",
    "command",
    "args",
    "effect",
    "cond",
    "if",
    "when",
    "unless",
    "else",
    "positional",
    "exact",
    "anywhere",
];

fn is_keyword(s: &str) -> bool {
    s.starts_with(':')
}
fn is_string(s: &str) -> bool {
    s.starts_with('"')
}
fn is_regex(s: &str) -> bool {
    s.starts_with("#\"")
}
fn is_special_form(s: &str) -> bool {
    SPECIAL_FORMS.contains(&s)
}

// ── Formatting settings ─────────────────────────────────────────────

#[derive(Debug, Clone)]
pub struct Format {
    pub width: usize,
    pub color: bool,
    pub line_number: Option<usize>,
}

impl Default for Format {
    fn default() -> Self {
        Self {
            width: 72,
            color: false,
            line_number: None,
        }
    }
}

impl Format {
    pub fn colored() -> Self {
        Self {
            color: true,
            ..Self::default()
        }
    }
}

// ── Rendering ───────────────────────────────────────────────────────

/// Pretty-print a Doc with the given format settings.
pub fn pretty<A>(doc: &Doc<A>, indent: usize, fmt: &Format) -> String {
    let prefix_width = fmt.line_number.map_or(0, line_prefix_width);
    let content = render(doc, indent + prefix_width, fmt.width, fmt.color, false);

    match fmt.line_number {
        Some(n) => prepend_line_number(&content, n, fmt.color),
        None => content,
    }
}

fn line_prefix_width(n: usize) -> usize {
    format!("{n}").len() + 2
}

fn prepend_line_number(content: &str, n: usize, color: bool) -> String {
    let prefix = format!("{n}: ");
    let mut result = String::new();
    for (i, line) in content.lines().enumerate() {
        if i > 0 {
            result.push('\n');
        }
        if i == 0 {
            if color {
                result.push_str(&prefix.dimmed().to_string());
            } else {
                result.push_str(&prefix);
            }
        }
        result.push_str(line);
    }
    result
}

fn render<A>(doc: &Doc<A>, indent: usize, width: usize, color: bool, dimmed: bool) -> String {
    // Inherit dimmed from ancestors; once dimmed, stays dimmed.
    let dimmed = dimmed || doc.dimmed;
    match &doc.node {
        DocF::Atom(s) => render_atom(s, color, dimmed),
        DocF::List(children) if children.is_empty() => {
            if color {
                format!("{}{}", "(".dimmed(), ")".dimmed())
            } else {
                "()".into()
            }
        }
        DocF::List(children) => {
            if let Some(head) = children.first().and_then(|c| c.as_atom()) {
                match head {
                    "rule" => {
                        let broken = render_broken(children, indent, width, color, dimmed);
                        if max_line_width(&broken, indent) <= width {
                            return broken;
                        }
                        return render_all_drop(children, indent, width, color, dimmed);
                    }
                    "cond" => return render_cond(children, indent, width, color, dimmed),
                    "if" | "when" | "unless" => {
                        return render_body_indent(children, indent, width, color, dimmed);
                    }
                    _ => {}
                }
            }

            // Skip flat when this node or any child requires breaking.
            let must_break = doc.layout == LayoutHint::AlwaysBreak
                || children.iter().any(|c| c.layout == LayoutHint::AlwaysBreak);
            if !must_break {
                let flat = render_flat(children, color, dimmed);
                if !flat.contains('\n') && indent + visible_len(&flat) <= width {
                    return flat;
                }
            }
            let broken = render_broken(children, indent, width, color, dimmed);
            // Accept broken layout if every line fits within the width.
            if max_line_width(&broken, indent) <= width {
                return broken;
            }
            // Last resort: drop all children to separate lines at indent+2.
            // (Special forms like when/if/unless are routed to
            // render_body_indent above and never reach here.)
            render_all_drop(children, indent, width, color, dimmed)
        }
        DocF::Vector(children) if children.is_empty() => {
            if color {
                format!("{}{}", "[".dimmed(), "]".dimmed())
            } else {
                "[]".into()
            }
        }
        DocF::Vector(children) => {
            let must_break = doc.layout == LayoutHint::AlwaysBreak
                || children.iter().any(|c| c.layout == LayoutHint::AlwaysBreak);
            if !must_break {
                let flat = render_flat_delim(children, color, dimmed, '[', ']');
                if !flat.contains('\n') && indent + visible_len(&flat) <= width {
                    return flat;
                }
            }
            let broken = render_broken_delim(children, indent, width, color, dimmed, '[', ']');
            if max_line_width(&broken, indent) <= width {
                return broken;
            }
            render_all_drop_delim(children, indent, width, color, dimmed, '[', ']')
        }
    }
}

/// Render an atom, respecting dimmed state. When dimmed, all atoms
/// render as dim text regardless of their syntactic role.
fn render_atom(s: &str, color: bool, dimmed: bool) -> String {
    if dimmed && color {
        s.dimmed().to_string()
    } else {
        colorize_atom(s, color)
    }
}

fn delim_pair(color: bool, open: char, close: char) -> (String, String) {
    if color {
        (
            open.to_string().dimmed().to_string(),
            close.to_string().dimmed().to_string(),
        )
    } else {
        (open.to_string(), close.to_string())
    }
}

fn render_flat_delim<A>(
    children: &[Doc<A>],
    color: bool,
    dimmed: bool,
    open: char,
    close: char,
) -> String {
    let (open, close) = delim_pair(color, open, close);
    let parts: Vec<String> = children
        .iter()
        .map(|c| render(c, 0, usize::MAX, color, dimmed))
        .collect();
    format!("{open}{}{close}", parts.join(" "))
}

fn render_broken_delim<A>(
    children: &[Doc<A>],
    indent: usize,
    width: usize,
    color: bool,
    dimmed: bool,
    open: char,
    close: char,
) -> String {
    let (open, close) = delim_pair(color, open, close);

    let head = render(&children[0], indent + 1, width, color, dimmed);
    let align = indent + visible_len(&head) + 2;

    let mut lines = Vec::new();

    if children.len() == 1 {
        lines.push(format!("{open}{head}{close}"));
    } else {
        let first_child = render(&children[1], align, width, color, dimmed);
        lines.push(format!("{open}{head} {first_child}"));

        for child in &children[2..] {
            let child_str = render(child, align, width, color, dimmed);
            lines.push(format!("{:pad$}{child_str}", "", pad = align));
        }
        if let Some(last) = lines.last_mut() {
            last.push_str(&close);
        }
    }

    lines.join("\n")
}

fn render_all_drop_delim<A>(
    children: &[Doc<A>],
    indent: usize,
    width: usize,
    color: bool,
    dimmed: bool,
    open: char,
    close: char,
) -> String {
    let (open, close) = delim_pair(color, open, close);

    let head = render(&children[0], indent + 1, width, color, dimmed);
    let child_indent = indent + 2;

    if children.len() == 1 {
        return format!("{open}{head}{close}");
    }

    let mut lines = vec![format!("{open}{head}")];
    for (i, child) in children[1..].iter().enumerate() {
        let is_last = i == children.len() - 2;
        let rendered = render(child, child_indent, width, color, dimmed);
        if is_last {
            lines.push(format!("{:pad$}{rendered}{close}", "", pad = child_indent));
        } else {
            lines.push(format!("{:pad$}{rendered}", "", pad = child_indent));
        }
    }

    lines.join("\n")
}

fn render_flat<A>(children: &[Doc<A>], color: bool, dimmed: bool) -> String {
    render_flat_delim(children, color, dimmed, '(', ')')
}

fn render_broken<A>(
    children: &[Doc<A>],
    indent: usize,
    width: usize,
    color: bool,
    dimmed: bool,
) -> String {
    render_broken_delim(children, indent, width, color, dimmed, '(', ')')
}

/// Render with all children dropped to new lines at indent+2.
/// Used for AlwaysBreak nodes where uniform child alignment is wanted.
fn render_all_drop<A>(
    children: &[Doc<A>],
    indent: usize,
    width: usize,
    color: bool,
    dimmed: bool,
) -> String {
    render_all_drop_delim(children, indent, width, color, dimmed, '(', ')')
}

fn render_cond<A>(
    children: &[Doc<A>],
    indent: usize,
    width: usize,
    color: bool,
    dimmed: bool,
) -> String {
    let open = if color {
        "(".dimmed().to_string()
    } else {
        "(".into()
    };
    let close = if color {
        ")".dimmed().to_string()
    } else {
        ")".into()
    };

    let head = render(&children[0], indent + 1, width, color, dimmed);
    let body_indent = indent + 2;

    let mut lines = vec![format!("{open}{head}")];

    for (i, clause) in children[1..].iter().enumerate() {
        let is_last = i == children.len() - 2;
        // Inherit dimmed from the clause node itself (e.g. unevaluated branches).
        let clause_dimmed = dimmed || clause.dimmed;
        match &clause.node {
            DocF::List(parts) if parts.len() >= 2 => {
                let clause_open = if color {
                    "(".dimmed().to_string()
                } else {
                    "(".into()
                };
                let clause_close = if color {
                    ")".dimmed().to_string()
                } else {
                    ")".into()
                };

                let test = render(&parts[0], body_indent + 1, width, color, clause_dimmed);
                lines.push(format!("{:pad$}{clause_open}{test}", "", pad = body_indent));

                let body_col = body_indent + 1;
                for (j, body_part) in parts[1..].iter().enumerate() {
                    let is_last_part = j == parts.len() - 2;
                    let rendered = render(body_part, body_col, width, color, clause_dimmed);
                    if is_last_part && is_last {
                        lines.push(format!(
                            "{:pad$}{rendered}{clause_close}{close}",
                            "",
                            pad = body_col
                        ));
                    } else if is_last_part {
                        lines.push(format!(
                            "{:pad$}{rendered}{clause_close}",
                            "",
                            pad = body_col
                        ));
                    } else {
                        lines.push(format!("{:pad$}{rendered}", "", pad = body_col));
                    }
                }
            }
            _ => {
                let rendered = render(clause, body_indent, width, color, clause_dimmed);
                if is_last {
                    lines.push(format!("{:pad$}{rendered}{close}", "", pad = body_indent));
                } else {
                    lines.push(format!("{:pad$}{rendered}", "", pad = body_indent));
                }
            }
        }
    }

    if children.len() == 1
        && let Some(last) = lines.last_mut()
    {
        last.push_str(&close);
    }

    lines.join("\n")
}

fn render_body_indent<A>(
    children: &[Doc<A>],
    indent: usize,
    width: usize,
    color: bool,
    dimmed: bool,
) -> String {
    let open = if color {
        "(".dimmed().to_string()
    } else {
        "(".into()
    };
    let close = if color {
        ")".dimmed().to_string()
    } else {
        ")".into()
    };

    let head = render(&children[0], indent + 1, width, color, dimmed);
    let body_indent = indent + 2;

    if children.len() == 1 {
        return format!("{open}{head}{close}");
    }

    // Try placing the first child on the same line as the head.
    let inline_col = indent + 1 + visible_len(&head) + 1;
    let first = render(&children[1], inline_col, width, color, dimmed);
    let first_multiline = first.contains('\n');

    let mut lines = if first_multiline {
        // First child wraps — drop it to the next line.
        // For predicate forms (when/if/unless), use extra indent (indent+4)
        // to visually distinguish the predicate from the body (at indent+2).
        let head_atom = children[0].as_atom().unwrap_or("");
        let is_predicate_form = matches!(head_atom, "when" | "if" | "unless");
        let first_indent = if is_predicate_form {
            indent + 4
        } else {
            body_indent
        };
        let first = render(&children[1], first_indent, width, color, dimmed);
        vec![
            format!("{open}{head}"),
            format!("{:pad$}{first}", "", pad = first_indent),
        ]
    } else {
        vec![format!("{open}{head} {first}")]
    };

    for (i, child) in children[2..].iter().enumerate() {
        let is_last = i == children.len() - 3;
        let rendered = render(child, body_indent, width, color, dimmed);
        if is_last {
            lines.push(format!("{:pad$}{rendered}{close}", "", pad = body_indent));
        } else {
            lines.push(format!("{:pad$}{rendered}", "", pad = body_indent));
        }
    }

    if children.len() == 2
        && let Some(last) = lines.last_mut()
    {
        last.push_str(&close);
    }

    lines.join("\n")
}

/// Colorize an atom value based on its content.
pub fn colorize_atom(s: &str, color: bool) -> String {
    if !color {
        return s.to_string();
    }
    if is_keyword(s) {
        s.truecolor(120, 120, 255).to_string()
    } else if is_string(s) || is_regex(s) {
        s.green().to_string()
    } else if is_special_form(s) {
        s.blue().to_string()
    } else {
        s.to_string()
    }
}

/// Widest visible line in a multi-line rendered string.
/// `base_indent` is added to the first line (which lacks indentation padding
/// because indentation is added by the caller).
fn max_line_width(rendered: &str, base_indent: usize) -> usize {
    rendered
        .lines()
        .enumerate()
        .map(|(i, line)| {
            let w = visible_len(line);
            if i == 0 { base_indent + w } else { w }
        })
        .max()
        .unwrap_or(0)
}

/// Visible length of a string, ignoring ANSI SGR escape sequences.
pub fn visible_len(s: &str) -> usize {
    let mut len = 0;
    let mut in_escape = false;
    for ch in s.chars() {
        if in_escape {
            if ch.is_ascii_alphabetic() {
                in_escape = false;
            }
        } else if ch == '\x1b' {
            in_escape = true;
        } else {
            len += 1;
        }
    }
    len
}

#[cfg(test)]
mod tests {
    use super::*;

    fn a(s: &str) -> Doc {
        Doc::atom(s)
    }

    fn l(children: Vec<Doc>) -> Doc {
        Doc::list(children)
    }

    fn v(children: Vec<Doc>) -> Doc {
        Doc::vector(children)
    }

    fn pp(doc: &Doc, width: usize) -> String {
        pretty(
            doc,
            0,
            &Format {
                width,
                ..Default::default()
            },
        )
    }

    fn pp_color(doc: &Doc, width: usize) -> String {
        pretty(
            doc,
            0,
            &Format {
                width,
                color: true,
                ..Default::default()
            },
        )
    }

    // ── Flat rendering ──────────────────────────────────────────────

    #[test]
    fn flat_empty_list() {
        assert_eq!(pp(&l(vec![]), 80), "()");
    }

    #[test]
    fn flat_simple_list() {
        assert_eq!(
            pp(&l(vec![a("command"), a("\"rm\"")]), 80),
            "(command \"rm\")"
        );
    }

    #[test]
    fn flat_vector() {
        assert_eq!(pp(&v(vec![a(":via/ssh")]), 80), "[:via/ssh]");
    }

    #[test]
    fn empty_vector() {
        assert_eq!(pp(&v(vec![]), 80), "[]");
    }

    #[test]
    fn vector_wraps_when_long() {
        let doc = v(vec![a(":ssh/host"), l(vec![a("regex"), a("\"^prod-\"")])]);
        let rendered = pp(&doc, 18);
        assert!(rendered.starts_with("[:ssh/host"));
        assert!(rendered.contains("(regex \"^prod-\")"));
        assert!(rendered.ends_with(']'));
    }

    #[test]
    fn flat_nested() {
        let doc = l(vec![a("rule"), l(vec![a("command"), a("\"rm\"")])]);
        assert_eq!(pp(&doc, 80), "(rule (command \"rm\"))");
    }

    // ── Wrapping ────────────────────────────────────────────────────

    #[test]
    fn wraps_when_exceeds_width() {
        let doc = l(vec![a("rule"), a("aaa"), a("bbb"), a("ccc")]);
        let result = pp(&doc, 15);
        assert_eq!(result, "(rule aaa\n      bbb\n      ccc)");
    }

    #[test]
    fn wraps_nested_lists() {
        let doc = l(vec![
            a("args"),
            l(vec![a("and"), a("xxxxxxxxxxxx"), a("yyyyyyyyyyyy")]),
        ]);
        let result = pp(&doc, 25);
        assert!(result.contains('\n'));
    }

    #[test]
    fn stays_flat_when_fits() {
        let doc = l(vec![a("command"), a("\"ls\"")]);
        let result = pp(&doc, 80);
        assert!(!result.contains('\n'));
    }

    #[test]
    fn single_child_wraps() {
        let doc = l(vec![a("a-very-long-form-name")]);
        let result = pp(&doc, 10);
        assert_eq!(result, "(a-very-long-form-name)");
    }

    // ── Coloring ────────────────────────────────────────────────────

    fn with_forced_color(f: impl FnOnce()) {
        colored::control::set_override(true);
        f();
        colored::control::unset_override();
    }

    #[test]
    fn keywords_get_colored() {
        with_forced_color(|| {
            let result = pp_color(&a(":deny"), 80);
            assert!(
                result.contains("\x1b["),
                "expected ANSI codes in: {result:?}"
            );
            assert!(result.contains("deny"));
        });
    }

    #[test]
    fn strings_get_colored() {
        with_forced_color(|| {
            let result = pp_color(&a("\"rm\""), 80);
            assert!(
                result.contains("\x1b["),
                "expected ANSI codes in: {result:?}"
            );
            assert!(result.contains("rm"));
        });
    }

    #[test]
    fn special_forms_get_colored() {
        with_forced_color(|| {
            let result = pp_color(&a("command"), 80);
            assert!(
                result.contains("\x1b["),
                "expected ANSI codes in: {result:?}"
            );
        });
    }

    #[test]
    fn plain_atoms_not_colored() {
        with_forced_color(|| {
            let result = pp_color(&a("foo"), 80);
            assert!(
                !result.contains("\x1b["),
                "unexpected ANSI codes in: {result:?}"
            );
        });
    }

    #[test]
    fn parens_dimmed_in_color_mode() {
        with_forced_color(|| {
            let result = pp_color(&l(vec![a("x")]), 80);
            assert!(
                result.contains("\x1b["),
                "expected ANSI codes in: {result:?}"
            );
        });
    }

    // ── from_sexpr ──────────────────────────────────────────────────

    #[test]
    fn from_sexpr_atom_bare() {
        let sexpr = may_i_sexpr::Sexpr::Atom("hello".into(), may_i_core::Span::new(0, 0));
        let doc = doc_from_sexpr(&sexpr);
        assert_eq!(pp(&doc, 80), "hello");
    }

    #[test]
    fn from_sexpr_atom_needs_quoting() {
        let sexpr = may_i_sexpr::Sexpr::Atom("hello world".into(), may_i_core::Span::new(0, 0));
        let doc = doc_from_sexpr(&sexpr);
        assert_eq!(pp(&doc, 80), "\"hello world\"");
    }

    #[test]
    fn from_sexpr_list() {
        let sexpr = may_i_sexpr::Sexpr::List(
            vec![
                may_i_sexpr::Sexpr::Atom("rule".into(), may_i_core::Span::new(0, 0)),
                may_i_sexpr::Sexpr::Atom("foo".into(), may_i_core::Span::new(0, 0)),
            ],
            may_i_core::Span::new(0, 0),
        );
        let doc = doc_from_sexpr(&sexpr);
        assert_eq!(pp(&doc, 80), "(rule foo)");
    }

    // ── visible_len ─────────────────────────────────────────────────

    #[test]
    fn visible_len_plain() {
