        let result = pp(&doc, 30);
        assert!(result.contains('\n'));
    }

    // ── line_number ────────────────────────────────────────────────

    #[test]
    fn line_number_single_line() {
        let doc = l(vec![a("rule"), l(vec![a("command"), a("\"curl\"")])]);
        let result = pretty(
            &doc,
            0,
            &Format {
                width: 80,
                line_number: Some(108),
                ..Default::default()
            },
        );
        assert_eq!(result, "108: (rule (command \"curl\"))");
    }

    #[test]
    fn line_number_wrapped_aligns() {
        let doc = l(vec![a("rule"), a("aaa"), a("bbb"), a("ccc")]);
        let result = pretty(
            &doc,
            0,
            &Format {
                width: 20,
                line_number: Some(5),
                ..Default::default()
            },
        );
        let lines: Vec<&str> = result.lines().collect();
        assert!(lines.len() > 1);
        assert!(lines[0].starts_with("5: "));
        assert!(lines[1].starts_with("         "));
    }

    #[test]
    fn line_number_accounts_for_width() {
        let doc = l(vec![a("rule"), l(vec![a("command"), a("\"curl\"")])]);
        let result = pretty(
            &doc,
            0,
            &Format {
                width: 30,
                line_number: Some(108),
                ..Default::default()
            },
        );
        assert!(!result.contains('\n'));
    }

    // ── map ────────────────────────────────────────────────────────

    #[test]
    fn map_tags_all_nodes() {
        let doc = l(vec![a("head"), a("child")]);
        let tagged = doc.map(&|()| 42);
        assert_eq!(tagged.ann, 42);
        if let DocF::List(children) = &tagged.node {
            assert_eq!(children[0].ann, 42);
            assert_eq!(children[1].ann, 42);
        } else {
            panic!("expected list");
        }
    }

    #[test]
    fn map_preserves_structure() {
        let doc = l(vec![a("x"), l(vec![a("y")])]);
        let tagged = doc.map(&|()| "ann");
        assert_eq!(pretty(&tagged, 0, &Format::default()), "(x (y))");
    }

    // ── fold ───────────────────────────────────────────────────────

    #[test]
    fn fold_counts_nodes() {
        let doc = l(vec![a("a"), l(vec![a("b"), a("c")])]);
        let count: usize = doc.fold(&|node, _ann| match node {
            DocF::Atom(_) => 1,
            DocF::List(children) | DocF::Vector(children) => 1 + children.iter().sum::<usize>(),
        });
        assert_eq!(count, 5); // list + a + list + b + c
    }

    #[test]
    fn fold_collects_atoms() {
        let doc = l(vec![a("rule"), a("foo"), l(vec![a("bar")])]);
        let atoms: Vec<String> = doc.fold(&|node, _ann| match node {
            DocF::Atom(s) => vec![s],
            DocF::List(children) | DocF::Vector(children) => {
                children.into_iter().flatten().collect()
            }
        });
        assert_eq!(atoms, vec!["rule", "foo", "bar"]);
    }

    #[test]
    fn fold_rebuilds_tree() {
        // Use fold to rebuild a tree with truncated atoms.
        let doc = l(vec![a("hello-world"), a("short")]);
        let truncated: Doc<()> = doc.fold(&|node, _ann| match node {
            DocF::Atom(s) => {
                let t = if s.len() > 5 { &s[..5] } else { &s };
                Doc::atom(t)
            }
            DocF::List(children) => Doc::list(children),
            DocF::Vector(children) => Doc::vector(children),
        });
        assert_eq!(pp(&truncated, 80), "(hello short)");
    }

    // ── DocF::map ──────────────────────────────────────────────────

    #[test]
    fn docf_map_transforms_children() {
        let layer: DocF<i32> = DocF::List(vec![1, 2, 3]);
        let doubled = layer.map(|x| x * 2);
        assert_eq!(doubled.children(), Some(&[2, 4, 6][..]));
    }

    #[test]
    fn docf_map_atom_is_identity() {
        let layer: DocF<i32> = DocF::Atom("hello".into());
        let mapped = layer.map(|x| x * 2);
        assert_eq!(mapped.as_atom(), Some("hello"));
    }

    // ── AlwaysBreak ────────────────────────────────────────────────

    #[test]
    fn always_break_uses_broken_layout() {
        // AlwaysBreak skips flat but still uses broken (align-under-first-arg).
        let doc = Doc::broken_list(vec![a("or"), a("\"a\""), a("\"b\""), a("\"c\"")]);
        let result = pp(&doc, 80);
        assert_eq!(result, "(or \"a\"\n    \"b\"\n    \"c\")");
    }

    #[test]
    fn always_break_single_child() {
        let doc = Doc::broken_list(vec![a("or")]);
        let result = pp(&doc, 80);
        assert_eq!(result, "(or)");
    }

    #[test]
    fn always_break_falls_back_to_all_drop_at_narrow_width() {
        // At narrow width, broken layout overflows → falls to render_all_drop.
        let doc = Doc::broken_list(vec![
            a("or"),
            a("\"long-value-one\""),
            a("\"long-value-two\""),
        ]);
        let result = pp(&doc, 20);
        assert_eq!(result, "(or\n  \"long-value-one\"\n  \"long-value-two\")");
    }

    #[test]
    fn cond_renders_clauses() {
        let doc = l(vec![
            a("cond"),
            l(vec![a("\"a\""), a(":allow")]),
            l(vec![a("\"b\""), a(":deny")]),
        ]);
        let result = pp(&doc, 40);
        assert!(result.contains("cond"));
        assert!(result.contains("\"a\""));
        assert!(result.contains(":allow"));
        assert!(result.contains("\"b\""));
        assert!(result.contains(":deny"));
    }

    #[test]
    fn cond_single_child() {
        let doc = l(vec![a("cond")]);
        let result = pp(&doc, 40);
        assert_eq!(result, "(cond)");
    }

    #[test]
    fn cond_atom_clause() {
        let doc = l(vec![a("cond"), a("else")]);
        let result = pp(&doc, 40);
        assert!(result.contains("cond"));
        assert!(result.contains("else"));
    }

    #[test]
    fn body_indent_multiline_first_child() {
        // when/if/unless use body-indent; if the predicate wraps it
        // gets extra indent (indent+4) to distinguish from body.
        let pred = l(vec![a("and"), a("xxxxxxxxxxxx"), a("yyyyyyyyyyyy")]);
        let doc = l(vec![a("when"), pred, a(":allow")]);
        let result = pp(&doc, 25);
        let lines: Vec<&str> = result.lines().collect();
        assert!(lines.len() >= 3);
        assert!(lines[0].contains("when"));
    }

    #[test]
    fn body_indent_two_children() {
        // (when pred) — only head + one child, exercises the len==2 close path.
        let pred = l(vec![a("and"), a("xxxxx"), a("yyyyy")]);
        let doc = l(vec![a("when"), pred]);
        let result = pp(&doc, 15);
        assert!(result.contains("when"));
    }

    #[test]
    fn breaking_descendant_prevents_flat() {
        // (? (and (or "a" "b") "--")) where (or ...) is AlwaysBreak.
        // Even at wide width, (? ...) must not flatten since the or
        // descendant would render at indent=0 producing wrong columns.
        let or_doc = Doc::broken_list(vec![a("or"), a("\"a\""), a("\"b\"")]);
        let and_doc = l(vec![a("and"), or_doc, a("\"--\"")]);
        let q_doc = l(vec![a("?"), and_doc]);
        let result = pp(&q_doc, 80);
        // The (or ...) children must be indented relative to their parent,
        // not at column 0.
        for line in result.lines().skip(1) {
            let leading = line.len() - line.trim_start().len();
            assert!(leading >= 2, "line has too little indent: {result:?}");
        }
    }

    // ── Dimmed rendering ─────────────────────────────────────────────

    #[test]
    fn dimmed_atom_renders_dimmed() {
        with_forced_color(|| {
            let doc = Doc {
                dimmed: true,
                ..a("command")
            };
            let result = pp_color(&doc, 80);
            // Should contain ANSI (dimmed), but not the blue syntax color.
            assert!(result.contains("\x1b["), "expected ANSI in: {result:?}");
            assert!(result.contains("command"));
        });
    }

    #[test]
    fn dimmed_inherits_to_children() {
        with_forced_color(|| {
            // Parent list is dimmed → children should also render dimmed.
            let doc = Doc {
                ann: (),
                node: DocF::List(vec![a("rule"), a(":allow")]),
                layout: LayoutHint::Auto,
                dimmed: true,
            };
            let result = pp_color(&doc, 80);
            assert!(result.contains("rule"));
            assert!(result.contains(":allow"));
        });
    }

    #[test]
    fn dimmed_only_affects_flagged_subtree() {
        with_forced_color(|| {
            // One child dimmed, sibling not — sibling retains syntax color.
            let dimmed_child = Doc {
                dimmed: true,
                ..a("\"dimmed\"")
            };
            let normal_child = a("\"bright\"");
            let doc = l(vec![a("or"), dimmed_child, normal_child]);
            let result = pp_color(&doc, 80);
            // Both should be present.
            assert!(result.contains("dimmed"));
            assert!(result.contains("bright"));
        });
    }
}

// ── Property-based tests ────────────────────────────────────────────

#[cfg(test)]
mod prop_tests {
    use super::*;
    use proptest::prelude::*;

    /// Generate an arbitrary Doc tree (atoms and nested lists).
    fn arb_doc() -> impl Strategy<Value = Doc> {
        let leaf = "[a-z_]{1,12}".prop_map(|s| Doc::atom(s));
        leaf.prop_recursive(4, 20, 5, |inner| {
            prop_oneof![
                // Plain list.
                prop::collection::vec(inner.clone(), 0..5).prop_map(Doc::list),
                // List with a head atom (common in s-expressions).
                (
                    "[a-z]{1,8}".prop_map(|s| Doc::atom(s)),
                    prop::collection::vec(inner, 0..4),
                )
                    .prop_map(|(head, mut children)| {
                        children.insert(0, head);
                        Doc::list(children)
                    }),
            ]
        })
    }

    /// Count open and close parens in visible text.
    fn count_parens(s: &str) -> (usize, usize) {
        let mut in_escape = false;
        let (mut open, mut close) = (0, 0);
        for ch in s.chars() {
            if in_escape {
                if ch.is_ascii_alphabetic() {
                    in_escape = false;
                }
            } else if ch == '\x1b' {
                in_escape = true;
            } else if ch == '(' {
                open += 1;
            } else if ch == ')' {
                close += 1;
            }
        }
        (open, close)
    }

    proptest! {
        // ── Balanced parentheses ─────────────────────────────────────

        #[test]
        fn balanced_parens(doc in arb_doc(), width in 10..120usize) {
            let result = pretty(&doc, 0, &Format { width, ..Default::default() });
            let (open, close) = count_parens(&result);
            prop_assert_eq!(open, close,
                "unbalanced parens in: {:?}", result);
        }

        #[test]
        fn balanced_parens_with_color(doc in arb_doc(), width in 10..120usize) {
            colored::control::set_override(true);
            let result = pretty(&doc, 0, &Format { width, color: true, ..Default::default() });
            colored::control::unset_override();
            let (open, close) = count_parens(&result);
            prop_assert_eq!(open, close,
                "unbalanced parens (colored) in: {:?}", result);
        }

        // ── Width constraints ────────────────────────────────────────

        #[test]
        fn no_line_exceeds_width_by_much(doc in arb_doc(), width in 20..120usize) {
            let result = pretty(&doc, 0, &Format { width, ..Default::default() });
            // Lines may exceed width for long atoms, but the overflow
            // should be bounded by the longest atom in the tree.
            let max_atom_len = doc.fold(&|node, _ann: &()| -> usize {
                match node {
                    DocF::Atom(s) => s.len(),
                    DocF::List(cs) | DocF::Vector(cs) => cs.into_iter().max().unwrap_or(0),
                }
            });
            let slack = max_atom_len + 10; // parens + spaces
            for line in result.lines() {
                let vis = visible_len(line);
                prop_assert!(vis <= width + slack,
                    "line too wide ({vis} vs width {width} + slack {slack}): {line:?}");
            }
        }

        // ── Color transparency ───────────────────────────────────────

        #[test]
        fn color_preserves_visible_text(doc in arb_doc(), width in 10..120usize) {
            let plain = pretty(&doc, 0, &Format { width, ..Default::default() });

            colored::control::set_override(true);
            let colored_output = pretty(&doc, 0, &Format { width, color: true, ..Default::default() });
            colored::control::unset_override();

            // Strip ANSI codes from colored output and compare.
            let stripped = strip_ansi(&colored_output);
            prop_assert_eq!(plain, stripped,
                "color changed visible text");
        }

        // ── Atom roundtrip ───────────────────────────────────────────

        #[test]
        fn atom_renders_as_itself(s in "[a-z_]{1,20}") {
            let doc = Doc::atom(&s);
            let result = pretty(&doc, 0, &Format::default());
            prop_assert_eq!(result, s);
        }
    }

    fn strip_ansi(s: &str) -> String {
        let mut result = String::new();
        let mut in_escape = false;
        for ch in s.chars() {
            if in_escape {
                if ch.is_ascii_alphabetic() {
                    in_escape = false;
                }
            } else if ch == '\x1b' {
                in_escape = true;
            } else {
                result.push(ch);
            }
        }
        result
    }
}

// Concrete Syntax Tree (CST) for s-expressions with trivia preservation.
//
// This module provides a CST that preserves all source formatting including
// whitespace and comments. It uses the "Cofree comonad" pattern where every
// node carries an annotation containing trivia and span information.
//
// Benefits:
// - Source-to-source transformations preserve formatting
// - Enables rewrite-based migration tools
// - Pattern matching still works on the structure

#![allow(clippy::vec_box)]

use crate::span::Span;

/// The shape of an s-expression node (structure without annotations).
#[derive(Debug, Clone, PartialEq)]
pub enum Shape {
    Atom(String),
    List(Vec<Box<CstNode>>),
    Vector(Vec<Box<CstNode>>),
}

/// Trivia annotation for CST nodes.
#[derive(Debug, Clone, PartialEq)]
pub struct TriviaAnn {
    pub leading: Vec<Trivia>,
    pub trailing: Vec<Trivia>,
    pub span: Span,
}

impl Default for TriviaAnn {
    fn default() -> Self {
        Self {
            leading: Vec::new(),
            trailing: Vec::new(),
            span: Span::new(0, 0),
        }
    }
}

/// A Concrete Syntax Tree node with trivia and span annotations.
#[derive(Debug, Clone, PartialEq)]
pub struct CstNode {
    pub annotation: TriviaAnn,
    pub shape: Shape,
}

/// Trivia types (comments and whitespace).
#[derive(Debug, Clone, PartialEq)]
pub enum Trivia {
    Whitespace(String),
    Comment { text: String, has_newline: bool },
}

impl Trivia {
    pub fn has_newline(&self) -> bool {
        match self {
            Trivia::Whitespace(s) => s.contains('\n'),
            Trivia::Comment { has_newline, .. } => *has_newline,
        }
    }

    pub fn as_str(&self) -> &str {
        match self {
            Trivia::Whitespace(s) => s,
            Trivia::Comment { text, .. } => text,
        }
    }
}

impl CstNode {
    /// Create an atom node.
    pub fn atom(value: impl Into<String>, ann: TriviaAnn) -> Self {
        Self {
            annotation: ann,
            shape: Shape::Atom(value.into()),
        }
    }

    /// Create a list node.
    pub fn list(children: Vec<Box<CstNode>>, ann: TriviaAnn) -> Self {
        Self {
            annotation: ann,
            shape: Shape::List(children),
        }
    }

    /// Create a vector node.
    pub fn vector(children: Vec<Box<CstNode>>, ann: TriviaAnn) -> Self {
        Self {
            annotation: ann,
            shape: Shape::Vector(children),
        }
    }

    /// Get the atom value if this is an atom.
    pub fn as_atom(&self) -> Option<&str> {
        match &self.shape {
            Shape::Atom(s) => Some(s),
            _ => None,
        }
    }

    /// Get list children if this is a list.
    pub fn as_list(&self) -> Option<&[Box<CstNode>]> {
        match &self.shape {
            Shape::List(children) => Some(children),
            _ => None,
        }
    }

    /// Check if this is a tagged list (first element is the given atom).
    pub fn is_tagged(&self, tag: &str) -> bool {
        self.as_list()
            .and_then(|children| children.first())
            .and_then(|first| first.as_atom())
            == Some(tag)
    }

    /// Serialize back to string.
    pub fn serialize(&self) -> String {
        let mut output = String::new();
        self.write_to(&mut output);
        output
    }

    fn write_to(&self, output: &mut String) {
        // Write leading trivia
        for trivia in &self.annotation.leading {
            match trivia {
                Trivia::Whitespace(s) => output.push_str(s),
                Trivia::Comment { text, has_newline } => {
                    output.push_str(text);
                    if *has_newline {
                        output.push('\n');
                    }
                }
            }
        }

        // Write the shape
        match &self.shape {
            Shape::Atom(s) => {
                if needs_quoting(s) {
                    output.push_str(&quote_string(s));
                } else {
                    output.push_str(s);
                }
            }
            Shape::List(children) => {
                output.push('(');
                for (i, child) in children.iter().enumerate() {
                    if i > 0 && child.annotation.leading.is_empty() {
                        output.push(' ');
                    }
                    child.write_to(output);
                }
                output.push(')');
            }
            Shape::Vector(children) => {
                output.push('[');
                for (i, child) in children.iter().enumerate() {
                    if i > 0 && child.annotation.leading.is_empty() {
                        output.push(' ');
                    }
                    child.write_to(output);
                }
                output.push(']');
            }
        }

        // Write trailing trivia
        for trivia in &self.annotation.trailing {
            match trivia {
                Trivia::Whitespace(s) => output.push_str(s),
                Trivia::Comment { text, has_newline } => {
                    output.push_str(text);
                    if *has_newline {
                        output.push('\n');
                    }
                }
            }
        }
    }

    /// Apply a transformation to this node and all children (cata-like).
    /// Returns Some(node) if a transformation occurred, None otherwise.
    pub fn transform<F>(&self, f: &mut F) -> Option<Box<CstNode>>
    where
        F: FnMut(&CstNode) -> Option<Box<CstNode>>,
    {
        // First try to apply the transformation to this node
        if let Some(replacement) = f(self) {
            return Some(replacement);
        }

        // If no transformation at this node, try children
        match &self.shape {
            Shape::Atom(_) => None,
            Shape::List(children) => {
                let mut new_children = Vec::new();
                let mut changed = false;
                for c in children {
                    if let Some(new_c) = c.transform(f) {
                        new_children.push(new_c);
                        changed = true;
                    } else {
                        new_children.push(c.clone());
                    }
                }
                if changed {
                    Some(Box::new(CstNode {
                        annotation: self.annotation.clone(),
                        shape: Shape::List(new_children),
                    }))
                } else {
                    None
                }
            }
            Shape::Vector(children) => {
                let mut new_children = Vec::new();
                let mut changed = false;
                for c in children {
                    if let Some(new_c) = c.transform(f) {
                        new_children.push(new_c);
                        changed = true;
                    } else {
                        new_children.push(c.clone());
                    }
                }
                if changed {
                    Some(Box::new(CstNode {
                        annotation: self.annotation.clone(),
                        shape: Shape::Vector(new_children),
                    }))
                } else {
                    None
                }
            }
        }
    }
}

fn needs_quoting(s: &str) -> bool {
    s.is_empty()
        || s.contains(|c: char| {
            c.is_whitespace()
                || c == '('
                || c == ')'
                || c == '['
                || c == ']'
                || c == '"'
                || c == ';'
                || c == '\\'
        })
}

fn quote_string(s: &str) -> String {
    format!("\"{}\"", s.replace('\\', "\\\\").replace('"', "\\\""))
}

/// Parse a string into CST nodes.
pub fn parse(input: &str) -> (Vec<Box<CstNode>>, Vec<crate::span::RawError>) {
    let mut parser = Parser::new(input);
    parser.parse()
}

struct Parser<'a> {
    input: &'a str,
    chars: std::iter::Peekable<std::str::CharIndices<'a>>,
    errors: Vec<crate::span::RawError>,
}

impl<'a> Parser<'a> {
    fn new(input: &'a str) -> Self {
        Self {
            input,
            chars: input.char_indices().peekable(),
            errors: Vec::new(),
        }
    }

    fn parse(&mut self) -> (Vec<Box<CstNode>>, Vec<crate::span::RawError>) {
        let mut results = Vec::new();

        while self.chars.peek().is_some() {
            let leading = self.collect_trivia();

            if let Some(node) = self.parse_node() {
                let mut node = node;
                node.annotation.leading = leading;
                node.annotation.trailing = self.collect_trivia();
                results.push(Box::new(node));
            } else if !leading.is_empty()
                && !results.is_empty()
                && let Some(last) = results.last_mut()
            {
                last.annotation.trailing.extend(leading);
            }
        }

        (results, std::mem::take(&mut self.errors))
    }

    fn collect_trivia(&mut self) -> Vec<Trivia> {
        let mut trivia = Vec::new();

        while let Some(&(pos, ch)) = self.chars.peek() {
            match ch {
                ' ' | '\t' | '\n' | '\r' => {
                    let _start = pos;
                    let mut ws = String::new();
                    while let Some(&(_, c)) = self.chars.peek() {
                        if c.is_whitespace() {
                            ws.push(c);
                            self.chars.next();
                        } else {
                            break;
                        }
                    }
                    if !ws.is_empty() {
                        trivia.push(Trivia::Whitespace(ws));
                    }
                }
                ';' => {
                    let _start = pos;
                    let mut comment = String::new();
                    comment.push(';');
                    self.chars.next();
                    let mut has_newline = false;
                    while let Some(&(_, c)) = self.chars.peek() {
                        self.chars.next();
                        if c == '\n' {
                            has_newline = true;
                            break;
                        }
                        comment.push(c);
                    }
                    trivia.push(Trivia::Comment {
                        text: comment,
                        has_newline,
                    });
                }
                _ => break,
            }
        }

        trivia
    }

    fn parse_node(&mut self) -> Option<CstNode> {
        let &(pos, ch) = self.chars.peek()?;

        match ch {
            '(' => self.parse_list(pos, ')'),
            '[' => self.parse_list(pos, ']'),
            '"' => self.parse_string(pos),
            _ if is_atom_char(ch) => self.parse_atom(pos),
            _ => {
                self.errors.push(crate::span::RawError::new(
                    format!("unexpected character: {:?}", ch),
                    Span::new(pos, pos + ch.len_utf8()),
                ));
                self.chars.next();
                None
            }
        }
    }

    fn parse_list(&mut self, start: usize, close: char) -> Option<CstNode> {
        self.chars.next(); // consume opening
        let mut children = Vec::new();

        loop {
            let leading = self.collect_trivia();

            if let Some(&(_pos, ch)) = self.chars.peek() {
                if ch == close {
                    self.chars.next();
                    break;
                }

                if let Some(mut child) = self.parse_node() {
                    child.annotation.leading = leading;
                    children.push(Box::new(child));
                } else if !leading.is_empty()
                    && !children.is_empty()
                    && let Some(last) = children.last_mut()
                {
                    last.annotation.trailing.extend(leading);
                }
            } else {
                self.errors.push(crate::span::RawError::new(
                    format!("unclosed list, expected '{}'", close),
                    Span::new(start, self.input.len()),
                ));
                break;
            }
        }

        let end = self
            .chars
            .peek()
            .map(|(p, _)| *p)
            .unwrap_or(self.input.len());

        let shape = if close == ')' {
            Shape::List(children)
        } else {
            Shape::Vector(children)
        };

        Some(CstNode {
            annotation: TriviaAnn {
                span: Span::new(start, end),
                ..Default::default()
            },
            shape,
        })
    }

    fn parse_string(&mut self, start: usize) -> Option<CstNode> {
        self.chars.next(); // consume opening quote
        let mut s = String::new();

        loop {
            match self.chars.next() {
                None => {
                    self.errors.push(crate::span::RawError::new(
                        "unterminated string",
                        Span::new(start, self.input.len()),
                    ));
                    return None;
                }
                Some((pos, '"')) => {
                    let end = pos + 1;
                    return Some(CstNode {
                        annotation: TriviaAnn {
                            span: Span::new(start, end),
                            ..Default::default()
                        },
                        shape: Shape::Atom(s),
                    });
                }
                Some((_, '\\')) => match self.chars.next() {
                    Some((_, '\\')) => s.push('\\'),
                    Some((_, '"')) => s.push('"'),
                    Some((_, 'n')) => s.push('\n'),
                    Some((_, 't')) => s.push('\t'),
                    Some((pos, c)) => {
                        self.errors.push(crate::span::RawError::new(
                            format!("unknown escape: \\{}", c),
                            Span::new(pos, pos + c.len_utf8()),
                        ));
                    }
                    None => {
                        self.errors.push(crate::span::RawError::new(
                            "unterminated escape",
                            Span::new(start, self.input.len()),
                        ));
                        return None;
                    }
                },
                Some((_, c)) => s.push(c),
            }
        }
    }

    fn parse_atom(&mut self, start: usize) -> Option<CstNode> {
        let mut s = String::new();
        let mut end = start;

        while let Some(&(pos, c)) = self.chars.peek() {
            if is_atom_char(c) {
                s.push(c);
                end = pos + c.len_utf8();
                self.chars.next();
            } else {
                break;
            }
        }

        if s.is_empty() {
            None
        } else {
            Some(CstNode {
                annotation: TriviaAnn {
                    span: Span::new(start, end),
                    ..Default::default()
                },
                shape: Shape::Atom(s),
            })
        }
    }
}

fn is_atom_char(c: char) -> bool {
    c.is_ascii_alphanumeric()
        || matches!(c, '-' | '_' | '*' | '.' | '/' | '^' | ':' | '+' | '?' | '=')
}

/// A rewrite rule for transforming s-expressions.
pub trait RewriteRule {
    /// Try to apply this rule to a node.
    /// Returns Some(new_node) if the rule matched and transformed the node,
    /// or None if the rule didn't match.
    fn apply(&self, node: &CstNode) -> Option<Box<CstNode>>;
}

/// Apply a sequence of rewrite rules until convergence.
pub fn rewrite_until_convergence<F>(node: Box<CstNode>, rules: &[F]) -> Box<CstNode>
where
    F: Fn(&CstNode) -> Option<Box<CstNode>>,
{
    let mut current = node;
    loop {
        let mut changed = false;

        // Apply rules in sequence
        for rule in rules {
            if let Some(new_node) = rule(&current) {
                current = new_node;
                changed = true;
                break; // Restart from first rule after a change
            }
        }

        if !changed {
            // Also transform children
            if let Some(new_current) = current.transform(&mut |n| {
                for rule in rules {
                    if let Some(r) = rule(n) {
                        return Some(r);
                    }
                }
                None
            }) {
                current = new_current;
            } else {
                // No changes to children either
                break;
            }
        }
    }

    current
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_roundtrip() {
        let input = "; header\n  (foo bar)  \n; footer\n";
        let (nodes, errors) = parse(input);
        assert!(errors.is_empty());
        let output = nodes.iter().map(|n| n.serialize()).collect::<String>();
        assert_eq!(input, output);
    }

    #[test]
    fn test_rewrite() {
        let input = "(old-syntax x)";
        let (nodes, _) = parse(input);
        let node = nodes.into_iter().next().unwrap();

        // Define a simple rewrite rule
        let rule = |n: &CstNode| {
            if n.is_tagged("old-syntax") {
                // Strip leading whitespace from children (it was separator space after the tag)
                let children: Vec<Box<CstNode>> = n
                    .as_list()?
                    .iter()
                    .skip(1)
                    .map(|c| {
                        let mut new_c = (**c).clone();
                        new_c.annotation.leading.clear();
                        Box::new(new_c)
                    })
                    .collect();
                Some(Box::new(CstNode::list(
                    children,
                    TriviaAnn {
                        leading: n.annotation.leading.clone(),
                        trailing: n.annotation.trailing.clone(),
                        ..Default::default()
                    },
                )))
            } else {
                None
            }
        };

        let rewritten = rewrite_until_convergence(node, &[rule]);
        assert_eq!(rewritten.serialize(), "(x)");
    }

    #[test]
    fn test_trivia_has_newline() {
        let ws_no_newline = Trivia::Whitespace("   ".to_string());
        let ws_with_newline = Trivia::Whitespace("  \n  ".to_string());
        let comment_no_newline = Trivia::Comment {
            text: "; comment".to_string(),
            has_newline: false,
        };
        let comment_with_newline = Trivia::Comment {
            text: "; comment".to_string(),
            has_newline: true,
        };

        assert!(!ws_no_newline.has_newline());
        assert!(ws_with_newline.has_newline());
        assert!(!comment_no_newline.has_newline());
        assert!(comment_with_newline.has_newline());
    }

    #[test]
    fn test_trivia_as_str() {
        let ws = Trivia::Whitespace("   ".to_string());
        let comment = Trivia::Comment {
            text: "; comment".to_string(),
            has_newline: false,
        };

        assert_eq!(ws.as_str(), "   ");
        assert_eq!(comment.as_str(), "; comment");
    }

    #[test]
    fn test_vector_creation_and_access() {
        let vec_node = CstNode::vector(
            vec![
                Box::new(CstNode::atom("a", Default::default())),
                Box::new(CstNode::atom("b", Default::default())),
            ],
            Default::default(),
        );

        assert_eq!(vec_node.serialize(), "[a b]");
    }

    #[test]
    fn test_vector_with_comments() {
        let input = "[a ;; comment\nb]";
        let (nodes, errors) = parse(input);
        assert!(errors.is_empty());
        assert_eq!(nodes.len(), 1);
        assert_eq!(nodes[0].serialize(), input);
    }

    #[test]
    fn test_transform_with_direct_replacement() {
        let input = "(old x)";
        let (nodes, _) = parse(input);
        let node = nodes.into_iter().next().unwrap();

        // Rule that replaces the root node directly
        let rule = |n: &CstNode| {
            if n.is_tagged("old") {
                Some(Box::new(CstNode::atom("new", Default::default())))
            } else {
                None
            }
        };

        let result = node.transform(&mut { rule }).unwrap();
        assert_eq!(result.serialize(), "new");
    }

    #[test]
    fn test_transform_vector_children() {
        let input = "[old1 old2]";
        let (nodes, _) = parse(input);
        let node = nodes.into_iter().next().unwrap();

        let rule = |n: &CstNode| {
            if n.as_atom() == Some("old1") {
                Some(Box::new(CstNode::atom("new1", Default::default())))
            } else {
                None
            }
        };

        let result = node.transform(&mut { rule }).unwrap();
        assert_eq!(result.serialize(), "[new1 old2]");
    }

    #[test]
    fn test_no_transform_when_no_changes() {
        let input = "(a b c)";
        let (nodes, _) = parse(input);
        let node = nodes.into_iter().next().unwrap();

        let rule = |_n: &CstNode| None;

        let result = node.transform(&mut { rule });
        assert!(result.is_none());
    }

    #[test]
    fn test_parse_unclosed_list() {
        let input = "(foo bar";
        let (nodes, errors) = parse(input);
        assert!(!errors.is_empty());
        assert_eq!(errors[0].message, "unclosed list, expected ')'");
        // Should still return partial node
        assert_eq!(nodes.len(), 1);
    }

    #[test]
    fn test_parse_unterminated_string() {
        let input = "\"foo";
        let (nodes, errors) = parse(input);
        assert!(!errors.is_empty());
        assert_eq!(errors[0].message, "unterminated string");
        assert!(nodes.is_empty());
    }

    #[test]
    fn test_parse_unknown_escape() {
        let input = "\"\\x\"";
        let (nodes, errors) = parse(input);
        assert!(!errors.is_empty());
        assert!(errors[0].message.contains("unknown escape"));
        // Should still return the node with partial string
        assert_eq!(nodes.len(), 1);
    }

    #[test]
    fn test_parse_unterminated_escape() {
        let input = "\"\\";
        let (nodes, errors) = parse(input);
        assert!(!errors.is_empty());
        assert_eq!(errors[0].message, "unterminated escape");
        assert!(nodes.is_empty());
    }

    #[test]
    fn test_trivia_between_forms() {
        // Test that trivia between forms gets attached correctly
        let input = "(a)   ;; comment\n(b)";
        let (nodes, errors) = parse(input);
        assert!(errors.is_empty());
        assert_eq!(nodes.len(), 2);
        // The comment should be attached to the second node's leading trivia
        // or the first node's trailing trivia
        let first = &nodes[0];
        let second = &nodes[1];
        let has_comment = first
            .annotation
            .trailing
            .iter()
            .any(|t| matches!(t, Trivia::Comment { .. }))
            || second
                .annotation
                .leading
                .iter()
                .any(|t| matches!(t, Trivia::Comment { .. }));
        assert!(
            has_comment,
            "Comment should be attached to either first node's trailing or second node's leading trivia"
        );
    }

    #[test]
    fn test_rewrite_until_convergence_multiple_changes() {
        let input = "(outer (inner x))";
        let (nodes, _) = parse(input);
        let node = nodes.into_iter().next().unwrap();

        // Rule that renames 'inner' to 'middle', then 'middle' to 'innermost'
        let rule = |n: &CstNode| {
            if n.is_tagged("inner") {
                let children: Vec<_> = n.as_list()?.iter().skip(1).cloned().collect();
                Some(Box::new(CstNode::list(
                    vec![
                        Box::new(CstNode::atom("middle", Default::default())),
                        children.into_iter().next().unwrap(),
                    ],
                    Default::default(),
                )))
            } else if n.is_tagged("middle") {
                let children: Vec<_> = n.as_list()?.iter().skip(1).cloned().collect();
                Some(Box::new(CstNode::list(
                    vec![
                        Box::new(CstNode::atom("innermost", Default::default())),
                        children.into_iter().next().unwrap(),
                    ],
                    Default::default(),
                )))
            } else {
                None
            }
        };

        let result = rewrite_until_convergence(node, &[rule]);
        assert!(result.serialize().contains("innermost"));
    }

    #[test]
    fn test_parse_vector_empty() {
        let input = "[]";
        let (nodes, errors) = parse(input);
        assert!(errors.is_empty());
        assert_eq!(nodes.len(), 1);
        assert_eq!(nodes[0].serialize(), "[]");
    }

    #[test]
    fn test_parse_vector_with_nested_list() {
        let input = "[a (b c) d]";
        let (nodes, errors) = parse(input);
        assert!(errors.is_empty());
        assert_eq!(nodes.len(), 1);
        assert_eq!(nodes[0].serialize(), "[a (b c) d]");
    }
}

pub mod cst;
mod sexpr;
mod span;

pub use cst::{
    CstNode, RewriteRule, Trivia, TriviaAnn, parse as parse_cst, rewrite_until_convergence,
};
pub use sexpr::{Sexpr, needs_quoting, parse, quote_atom};
pub use span::RawError;

// S-expression parser — R10f
// Zero-dependency parser producing Atom | List AST.
//
// Quoted strings: "hello\nworld" (supports \\, \", \n, \t)
// Bare atoms: letters, digits, - _ * . / ^ :
// Comments: ; to end of line
// Parentheses delimit lists. Square brackets delimit vector-style lists.

use crate::span::{RawError, Span};

/// S-expression AST node with source spans.
#[derive(Debug, Clone, Eq)]
pub enum Sexpr {
    Atom(String, Span),
    List(Vec<Sexpr>, Span),
    Vector(Vec<Sexpr>, Span),
}

/// PartialEq ignores spans so existing test assertions are preserved.
impl PartialEq for Sexpr {
    fn eq(&self, other: &Self) -> bool {
        match (self, other) {
            (Sexpr::Atom(a, _), Sexpr::Atom(b, _)) => a == b,
            (Sexpr::List(a, _), Sexpr::List(b, _)) => a == b,
            (Sexpr::Vector(a, _), Sexpr::Vector(b, _)) => a == b,
            _ => false,
        }
    }
}

impl Sexpr {
    /// Return the atom string, or `None` if this is a list.
    pub fn as_atom(&self) -> Option<&str> {
        match self {
            Sexpr::Atom(s, _) => Some(s),
            Sexpr::List(..) | Sexpr::Vector(..) => None,
        }
    }

    /// Return the list contents, or `None` if this is an atom.
    pub fn as_list(&self) -> Option<&[Sexpr]> {
        match self {
            Sexpr::Atom(..) => None,
            Sexpr::List(v, _) | Sexpr::Vector(v, _) => Some(v),
        }
    }

    pub fn is_vector(&self) -> bool {
        matches!(self, Sexpr::Vector(..))
    }

    /// Return the byte-offset span of this node.
    pub fn span(&self) -> Span {
        match self {
            Sexpr::Atom(_, s) | Sexpr::List(_, s) | Sexpr::Vector(_, s) => *s,
        }
    }
}

impl std::fmt::Display for Sexpr {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Sexpr::Atom(s, _) => {
                if needs_quoting(s) {
                    write!(f, "{}", quote_atom(s))
                } else {
                    write!(f, "{s}")
                }
            }
            Sexpr::List(items, _) => {
                write!(f, "(")?;
                for (i, item) in items.iter().enumerate() {
                    if i > 0 {
                        write!(f, " ")?;
                    }
                    write!(f, "{item}")?;
                }
                write!(f, ")")
            }
            Sexpr::Vector(items, _) => {
                write!(f, "[")?;
                for (i, item) in items.iter().enumerate() {
                    if i > 0 {
                        write!(f, " ")?;
                    }
                    write!(f, "{item}")?;
                }
                write!(f, "]")
            }
        }
    }
}

/// Returns true if a raw atom value needs quoting when displayed as an s-expression.
pub fn needs_quoting(s: &str) -> bool {
    s.is_empty()
        || s.contains(|c: char| {
            c.is_whitespace()
                || c == '('
                || c == ')'
                || c == '['
                || c == ']'
                || c == '"'
                || c == ';'
                || c == '\\'
        })
}

/// Quote an atom string for s-expression display, escaping backslashes and double quotes.
pub fn quote_atom(s: &str) -> String {
    format!("\"{}\"", s.replace('\\', "\\\\").replace('"', "\\\""))
}

// --- Tokenizer ---

#[derive(Debug)]
struct Token {
    kind: TokenKind,
    span: Span,
}

#[derive(Debug, Clone, PartialEq)]
enum TokenKind {
    Open,
    Close,
    OpenBracket,
    CloseBracket,
    Atom(String),
    Str(String),
}

fn is_atom_char(c: char) -> bool {
    c.is_ascii_alphanumeric()
        || matches!(c, '-' | '_' | '*' | '.' | '/' | '^' | ':' | '+' | '?' | '=')
}

fn tokenize(input: &str) -> Result<Vec<Token>, RawError> {
    let mut tokens = Vec::new();
    let mut chars = input.char_indices().peekable();

    while let Some(&(pos, ch)) = chars.peek() {
        match ch {
            ' ' | '\t' | '\n' | '\r' => {
                chars.next();
            }
            ';' => {
                // Comment: skip to end of line
                while let Some(&(_, c)) = chars.peek() {
                    chars.next();
                    if c == '\n' {
                        break;
                    }
                }
            }
            '(' => {
                tokens.push(Token {
                    kind: TokenKind::Open,
                    span: Span::new(pos, pos + 1),
                });
                chars.next();
            }
            ')' => {
                tokens.push(Token {
                    kind: TokenKind::Close,
                    span: Span::new(pos, pos + 1),
                });
                chars.next();
            }
            '[' => {
                tokens.push(Token {
                    kind: TokenKind::OpenBracket,
                    span: Span::new(pos, pos + 1),
                });
                chars.next();
            }
            ']' => {
                tokens.push(Token {
                    kind: TokenKind::CloseBracket,
                    span: Span::new(pos, pos + 1),
                });
                chars.next();
            }
            '"' => {
                let start = pos;
                chars.next();
                let mut s = String::new();
                loop {
                    match chars.next() {
                        None => {
                            return Err(RawError::new(
                                "unterminated string",
                                Span::new(start, input.len()),
                            ));
                        }
                        Some((end_pos, '"')) => {
                            tokens.push(Token {
                                kind: TokenKind::Str(s),
                                span: Span::new(start, end_pos + 1),
                            });
                            break;
                        }
                        Some((esc_pos, '\\')) => match chars.next() {
                            Some((_, '\\')) => s.push('\\'),
                            Some((_, '"')) => s.push('"'),
                            Some((_, 'n')) => s.push('\n'),
                            Some((_, 't')) => s.push('\t'),
                            Some((end_pos, c)) => {
                                return Err(RawError::new(
                                    format!("unknown escape: \\{c}"),
                                    Span::new(esc_pos, end_pos + c.len_utf8()),
                                ));
                            }
                            None => {
                                return Err(RawError::new(
                                    "unterminated escape in string",
                                    Span::new(esc_pos, input.len()),
                                ));
                            }
                        },
                        Some((_, c)) => s.push(c),
                    }
                }
            }
            c if is_atom_char(c) => {
                let start = pos;
                let mut s = String::new();
                let mut end = input.len();
                loop {
                    match chars.peek() {
                        Some(&(end_pos, c)) if is_atom_char(c) => {
                            s.push(c);
                            chars.next();
                        }
                        Some(&(end_pos, _)) => {
                            end = end_pos;
                            break;
                        }
                        None => break,
                    }
                }
                tokens.push(Token {
                    kind: TokenKind::Atom(s),
                    span: Span::new(start, end),
                });
            }
            _ => {
                return Err(RawError::new(
                    format!("unexpected character: {ch:?}"),
                    Span::new(pos, pos + ch.len_utf8()),
                ));
            }
        }
    }

    Ok(tokens)
}

// --- Parser ---

/// Return the 0-based column (byte offset from start of line) for an offset.
fn column_of(input: &str, offset: usize) -> usize {
    crate::span::offset_to_line_col(input, offset).1 - 1
}

/// Return the 0-based line number for an offset.
fn line_of(input: &str, offset: usize) -> usize {
    crate::span::offset_to_line_col(input, offset).0 - 1
}

/// Parse a string containing zero or more s-expressions into a list of top-level forms.
///
/// Returns all successfully parsed forms plus any accumulated errors.
/// An empty errors vec means the input was fully valid.
pub fn parse(input: &str) -> (Vec<Sexpr>, Vec<RawError>) {
    let tokens = match tokenize(input) {
        Ok(t) => t,
        Err(e) => return (vec![], vec![e]),
    };
    let mut pos = 0;
    let mut results: Vec<Sexpr> = Vec::new();
    let mut errors: Vec<RawError> = Vec::new();
    while pos < tokens.len() {
        // Case C: extra close at top level — recover by skipping
        if let Some(Token { kind, span }) = tokens.get(pos)
            && matches!(kind, TokenKind::Close | TokenKind::CloseBracket)
        {
            let (closer, opener) = match kind {
                TokenKind::Close => (")", "("),
                TokenKind::CloseBracket => ("]", "["),
                _ => unreachable!(),
            };
            let mut err = RawError::new(format!("unexpected '{closer}'"), *span)
                .with_label(format!("no matching '{opener}'"))
                .with_help(format!("remove this '{closer}'"));
            if let Some(prev) = results.last() {
                let prev_span = prev.span();
                err = err.with_secondary(
                    Span::new(prev_span.start, prev_span.start + 1),
                    "nearest form starts here",
                );
            }
            errors.push(err);
            pos += 1;
            continue;
        }
        let (sexpr, next) = parse_one(input, &tokens, pos, &mut errors);
        results.push(sexpr);
        pos = next;
    }
    (results, errors)
}

fn parse_one(
    input: &str,
    tokens: &[Token],
    pos: usize,
    errors: &mut Vec<RawError>,
) -> (Sexpr, usize) {
    match tokens.get(pos) {
        None => {
            // Should not happen — caller checks pos < tokens.len()
            errors.push(RawError::new("unexpected end of input", Span::new(0, 0)));
            (Sexpr::List(vec![], Span::new(0, 0)), pos)
        }
        Some(Token {
            kind: TokenKind::Close,
            span,
        }) => {
            // Should not happen — caller handles Case C
            errors.push(RawError::new("unexpected ')'", *span));
            (Sexpr::List(vec![], *span), pos + 1)
        }
        Some(Token {
            kind: TokenKind::CloseBracket,
            span,
        }) => {
            errors.push(RawError::new("unexpected ']'", *span));
            (Sexpr::Vector(vec![], *span), pos + 1)
        }
        Some(Token {
            kind: TokenKind::Atom(s) | TokenKind::Str(s),
            span,
        }) => (Sexpr::Atom(s.clone(), *span), pos + 1),
        Some(Token {
            kind: TokenKind::Open,
            span: open_span,
        }) => parse_delimited(input, tokens, pos, errors, *open_span, false),
        Some(Token {
            kind: TokenKind::OpenBracket,
            span: open_span,
        }) => parse_delimited(input, tokens, pos, errors, *open_span, true),
    }
}

fn parse_delimited(
    input: &str,
    tokens: &[Token],
    pos: usize,
    errors: &mut Vec<RawError>,
    open_span: Span,
    vector: bool,
) -> (Sexpr, usize) {
    let opener_col = column_of(input, open_span.start);
    let opener_line = line_of(input, open_span.start);
    let opener = if vector { '[' } else { '(' };
    let closer = if vector { ']' } else { ')' };
    let mut items: Vec<Sexpr> = Vec::new();
    let mut p = pos + 1;
    loop {
        match tokens.get(p) {
            None => {
                let label = match items.first().and_then(|s| s.as_atom()) {
                    Some(name) => format!("the {name} starting here"),
                    None => "starting here".to_string(),
                };
                let mut err = RawError::new(format!("unclosed '{opener}'"), open_span)
                    .with_label(label)
                    .with_help(format!("add a closing '{closer}'"));
                if let Some(last_item) = items.last() {
                    let last_span = last_item.span();
                    err = err.with_secondary(
                        Span::new(last_span.end, last_span.end),
                        "last item ends here",
                    );
                }
                errors.push(err);
                let span = Span::new(
                    open_span.start,
                    items.last().map_or(open_span.end, |i| i.span().end),
                );
                return (make_delimited(items, span, vector), p);
            }
            Some(Token {
                kind,
                span: close_span,
            }) if if vector {
                matches!(kind, TokenKind::CloseBracket)
            } else {
                matches!(kind, TokenKind::Close)
            } =>
            {
                let span = Span::new(open_span.start, close_span.end);
                return (make_delimited(items, span, vector), p + 1);
            }
            Some(Token {
                kind: TokenKind::Open | TokenKind::OpenBracket,
                span: next_span,
            }) => {
                let next_col = column_of(input, next_span.start);
                let next_line = line_of(input, next_span.start);
                if !items.is_empty() && next_line > opener_line && next_col == opener_col {
                    let insert_point = items.last().unwrap().span().end;
                    let label = match items.first().and_then(|s| s.as_atom()) {
                        Some(name) => format!("the {name} starting here"),
                        None => "starting here".to_string(),
                    };
                    let mut err = RawError::new(format!("unclosed '{opener}'"), open_span)
                        .with_label(label)
                        .with_help(format!("add a closing '{closer}'"));
                    err = err.with_secondary(
                        Span::new(insert_point, insert_point),
                        format!("insert '{closer}' here"),
                    );
                    errors.push(err);
                    let span = Span::new(open_span.start, insert_point);
                    return (make_delimited(items, span, vector), p);
                }
                let (item, next) = parse_one(input, tokens, p, errors);
                items.push(item);
                p = next;
            }
            _ => {
                let (item, next) = parse_one(input, tokens, p, errors);
                items.push(item);
                p = next;
            }
        }
    }
}

fn make_delimited(items: Vec<Sexpr>, span: Span, vector: bool) -> Sexpr {
    if vector {
        Sexpr::Vector(items, span)
    } else {
        Sexpr::List(items, span)
    }
}

#[cfg(test)]
