#[cfg(test)]
pub(crate) fn extract_simple_commands(cmd: &Command) -> Vec<&SimpleCommand> {
    let mut result = Vec::new();
    collect_simple_commands(cmd, &mut result);
    result
}

#[cfg(test)]
fn collect_simple_commands<'a>(cmd: &'a Command, out: &mut Vec<&'a SimpleCommand>) {
    if let Command::Simple(sc) = cmd {
        out.push(sc);
    }
    for child in cmd.children() {
        collect_simple_commands(child, out);
    }
}

#[cfg(test)]
pub(crate) fn extract_all_words(cmd: &Command) -> Vec<&Word> {
    let mut result = Vec::new();
    collect_all_words(cmd, &mut result);
    result
}

#[cfg(test)]
fn collect_all_words<'a>(cmd: &'a Command, out: &mut Vec<&'a Word>) {
    match cmd {
        Command::Simple(sc) => {
            out.extend(&sc.words);
            out.extend(sc.assignments.iter().map(|a| &a.value));
            for r in &sc.redirections {
                if let RedirectionTarget::File(w) = &r.target {
                    out.push(w);
                }
            }
        }
        Command::For { words, .. } => {
            out.extend(words);
        }
        Command::Case { word, arms, .. } => {
            out.push(word);
            for arm in arms {
                out.extend(&arm.patterns);
            }
        }
        Command::Redirected { redirections, .. } => {
            for r in redirections {
                if let RedirectionTarget::File(w) = &r.target {
                    out.push(w);
                }
            }
        }
        Command::Assignment(a) => {
            out.push(&a.value);
        }
        _ => {}
    }
    for child in cmd.children() {
        collect_all_words(child, out);
    }
}

#[cfg(test)]
pub(crate) fn find_structural_dynamic_parts(
    cmd: &Command,
    env: &std::collections::HashMap<String, String>,
) -> Vec<String> {
    let mut out = Vec::new();
    collect_structural_dynamic_parts(cmd, env, &mut out);
    out
}

#[cfg(test)]
fn collect_structural_dynamic_parts(
    cmd: &Command,
    env: &std::collections::HashMap<String, String>,
    out: &mut Vec<String>,
) {
    match cmd {
        Command::For { words, .. } => {
            for w in words {
                out.extend(w.resolve(env).dynamic_parts());
            }
        }
        Command::Case { word, arms, .. } => {
            out.extend(word.resolve(env).dynamic_parts());
            for arm in arms {
                for p in &arm.patterns {
                    out.extend(p.resolve(env).dynamic_parts());
                }
            }
        }
        _ => {}
    }
    for child in cmd.children() {
        collect_structural_dynamic_parts(child, env, out);
    }
}

use super::ast::*;
use super::lexer::{Lexer, Token};

pub(super) struct Parser {
    tokens: Vec<Token>,
    pos: usize,
}

impl Parser {
    pub(super) fn new(input: &str) -> Self {
        let mut lexer = Lexer::new(input);
        let tokens = lexer.tokenize();
        Parser { tokens, pos: 0 }
    }

    fn peek(&self) -> &Token {
        self.tokens.get(self.pos).unwrap_or(&Token::Eof)
    }

    fn advance(&mut self) -> Token {
        let tok = self.tokens.get(self.pos).cloned().unwrap_or(Token::Eof);
        if self.pos < self.tokens.len() {
            self.pos += 1;
        }
        tok
    }

    fn at_eof(&self) -> bool {
        matches!(self.peek(), Token::Eof)
    }

    fn expect(&mut self, expected: &Token) -> bool {
        if self.peek() == expected {
            self.advance();
            true
        } else {
            false
        }
    }

    fn skip_newlines(&mut self) {
        while matches!(self.peek(), Token::Newline) {
            self.advance();
        }
    }

    pub(super) fn parse_complete(&mut self) -> Command {
        self.skip_newlines();
        if self.at_eof() {
            return Command::Simple(SimpleCommand {
                assignments: vec![],
                words: vec![],
                redirections: vec![],
            });
        }
        self.parse_list()
    }

    fn parse_list(&mut self) -> Command {
        let mut commands = Vec::new();
        let first = self.parse_and_or();
        commands.push(first);

        loop {
            match self.peek().clone() {
                Token::Semi => {
                    self.advance();
                    self.skip_newlines();
                    if self.is_list_terminator() {
                        break;
                    }
                    let next = self.parse_and_or();
                    commands.push(next);
                }
                Token::Amp => {
                    self.advance();
                    let last = commands.pop().unwrap();
                    commands.push(Command::Background(Box::new(last)));
                    self.skip_newlines();
                    if self.is_list_terminator() {
                        break;
                    }
                    let next = self.parse_and_or();
                    commands.push(next);
                }
                Token::Newline => {
                    self.advance();
                    self.skip_newlines();
                    if self.is_list_terminator() {
                        break;
                    }
                    let next = self.parse_and_or();
                    commands.push(next);
                }
                _ => break,
            }
        }

        if commands.len() == 1 {
            commands.pop().unwrap()
        } else {
            Command::Sequence(commands)
        }
    }

    fn is_list_terminator(&self) -> bool {
        matches!(
            self.peek(),
            Token::Eof
                | Token::RParen
                | Token::RBrace
                | Token::Fi
                | Token::Done
                | Token::Esac
                | Token::Else
                | Token::Elif
                | Token::Then
                | Token::Do
                | Token::DoubleSemi
                | Token::SemiAmp
                | Token::DoubleSemiAmp
        )
    }

    fn parse_and_or(&mut self) -> Command {
        let mut left = self.parse_pipeline();

        loop {
            match self.peek().clone() {
                Token::And => {
                    self.advance();
                    self.skip_newlines();
                    let right = self.parse_pipeline();
                    left = Command::And(Box::new(left), Box::new(right));
                }
                Token::Or => {
                    self.advance();
                    self.skip_newlines();
                    let right = self.parse_pipeline();
                    left = Command::Or(Box::new(left), Box::new(right));
                }
                _ => break,
            }
        }

        left
    }

    fn parse_pipeline(&mut self) -> Command {
        let mut commands = Vec::new();
        commands.push(self.parse_command());

        while matches!(self.peek(), Token::Pipe) {
            self.advance();
            self.skip_newlines();
            commands.push(self.parse_command());
        }

        if commands.len() == 1 {
            commands.pop().unwrap()
        } else {
            Command::Pipeline(commands)
        }
    }

    fn parse_command(&mut self) -> Command {
        let cmd = match self.peek().clone() {
            Token::If => self.parse_if(),
            Token::For => self.parse_for(),
            Token::While => self.parse_while(),
            Token::Until => self.parse_until(),
            Token::Case => self.parse_case(),
            Token::Function => self.parse_function_def(),
            Token::LParen => self.parse_subshell(),
            Token::LBrace => self.parse_brace_group(),
            _ => return self.parse_simple_command(),
        };
        self.maybe_wrap_redirections(cmd)
    }

    fn maybe_wrap_redirections(&mut self, cmd: Command) -> Command {
        let mut redirections = Vec::new();
        while let Token::Redirect(ref r) = self.peek().clone() {
            redirections.push(r.clone());
            self.advance();
        }
        if redirections.is_empty() {
            cmd
        } else {
            Command::Redirected {
                command: Box::new(cmd),
                redirections,
            }
        }
    }

    fn parse_simple_command(&mut self) -> Command {
        let mut assignments = Vec::new();
        let mut words = Vec::new();
        let mut redirections = Vec::new();

        loop {
            match self.peek().clone() {
                Token::Word(ref w) => {
                    // Check for assignment (VAR=value) before any command words
                    if words.is_empty()
                        && let Some(assignment) = self.try_parse_assignment()
                    {
                        assignments.push(assignment);
                        continue;
                    }
                    let word = w.clone();
                    self.advance();
                    words.push(word);

                    // Check for POSIX function definition: name() { body }
                    if words.len() == 1
                        && assignments.is_empty()
                        && matches!(self.peek(), Token::LParen)
                    {
                        // Peek further for RParen
                        if self
                            .tokens
                            .get(self.pos + 1)
                            .is_some_and(|t| matches!(t, Token::RParen))
                        {
                            let name = words.pop().unwrap().to_str();
                            self.advance(); // skip LParen
                            self.advance(); // skip RParen
                            self.skip_newlines();
                            let body = self.parse_command();
                            return Command::FunctionDef {
                                name,
                                body: Box::new(body),
                            };
                        }
                    }
                }
                Token::Redirect(ref r) => {
                    let redir = r.clone();
                    self.advance();
                    redirections.push(redir);
                }
                _ => break,
            }
        }

        // If only assignments and no words, return as assignment command
        if !assignments.is_empty() && words.is_empty() && assignments.len() == 1 {
            return Command::Assignment(assignments.pop().unwrap());
        }

        Command::Simple(SimpleCommand {
            assignments,
            words,
            redirections,
        })
    }

    fn try_parse_assignment(&mut self) -> Option<Assignment> {
        if let Token::Word(ref w) = self.peek().clone()
            && !w.parts.is_empty()
            && let WordPart::Literal(ref s) = w.parts[0]
            && let Some(eq_pos) = s.find('=')
        {
            let name = &s[..eq_pos];
            if !name.is_empty()
                && name.chars().all(|c| c.is_ascii_alphanumeric() || c == '_')
                && name.chars().next().is_some_and(|c| !c.is_ascii_digit())
            {
                let value_start = &s[eq_pos + 1..];
                let mut value_parts = Vec::new();
                if !value_start.is_empty() {
                    value_parts.push(WordPart::Literal(value_start.to_string()));
                }
                // Include additional word parts
                for part in &w.parts[1..] {
                    value_parts.push(part.clone());
                }
                let value = if value_parts.is_empty() {
                    Word::literal("")
                } else {
                    Word { parts: value_parts }
                };
                let name = name.to_string();
                self.advance();
                return Some(Assignment { name, value });
            }
        }
        None
    }

    fn parse_if(&mut self) -> Command {
        self.advance(); // skip 'if'
        self.skip_newlines();
        let condition = self.parse_list();
        self.skip_newlines();
        self.expect(&Token::Then);
        self.skip_newlines();
        let then_branch = self.parse_list();

        let mut elif_branches = Vec::new();
        let mut else_branch = None;

        loop {
            self.skip_newlines();
            match self.peek().clone() {
                Token::Elif => {
                    self.advance();
                    self.skip_newlines();
                    let cond = self.parse_list();
                    self.skip_newlines();
                    self.expect(&Token::Then);
                    self.skip_newlines();
                    let body = self.parse_list();
                    elif_branches.push((cond, body));
                }
                Token::Else => {
                    self.advance();
                    self.skip_newlines();
                    let body = self.parse_list();
                    else_branch = Some(Box::new(body));
                    break;
                }
                _ => break,
            }
        }

        self.skip_newlines();
        self.expect(&Token::Fi);

        Command::If {
            condition: Box::new(condition),
            then_branch: Box::new(then_branch),
            elif_branches,
            else_branch,
        }
    }

    fn parse_for(&mut self) -> Command {
        self.advance(); // skip 'for'
        self.skip_newlines();

        let var = if let Token::Word(w) = self.advance() {
            w.to_str()
        } else {
            String::new()
        };

        self.skip_newlines();
        let mut words = Vec::new();

        if matches!(self.peek(), Token::In) {
            self.advance(); // skip 'in'
            while let Token::Word(w) = self.peek().clone() {
                words.push(w.clone());
                self.advance();
            }
        }

        // Skip separator (;  or newline)
        if matches!(self.peek(), Token::Semi | Token::Newline) {
            self.advance();
        }
        self.skip_newlines();
        self.expect(&Token::Do);
        self.skip_newlines();
        let body = self.parse_list();
        self.skip_newlines();
        self.expect(&Token::Done);

        Command::For {
            var,
            words,
            body: Box::new(body),
        }
    }

    fn parse_while(&mut self) -> Command {
        self.advance(); // skip 'while'
        self.skip_newlines();
        let condition = self.parse_list();
        self.skip_newlines();
        self.expect(&Token::Do);
        self.skip_newlines();
        let body = self.parse_list();
        self.skip_newlines();
        self.expect(&Token::Done);

        Command::Loop {
            kind: LoopKind::While,
            condition: Box::new(condition),
            body: Box::new(body),
        }
    }

    fn parse_until(&mut self) -> Command {
        self.advance(); // skip 'until'
        self.skip_newlines();
        let condition = self.parse_list();
        self.skip_newlines();
        self.expect(&Token::Do);
        self.skip_newlines();
        let body = self.parse_list();
        self.skip_newlines();
        self.expect(&Token::Done);

        Command::Loop {
            kind: LoopKind::Until,
            condition: Box::new(condition),
            body: Box::new(body),
        }
    }

    fn parse_case(&mut self) -> Command {
        self.advance(); // skip 'case'
        self.skip_newlines();

        let word = if let Token::Word(w) = self.advance() {
            w
        } else {
            Word::literal("")
        };

        self.skip_newlines();
        self.expect(&Token::In);
        self.skip_newlines();

        let mut arms = Vec::new();

        while !matches!(self.peek(), Token::Esac | Token::Eof) {
            // Skip optional (
            if matches!(self.peek(), Token::LParen) {
                self.advance();
            }

            // Read patterns separated by |
            let mut patterns = Vec::new();
            while let Token::Word(w) = self.peek().clone() {
                patterns.push(w.clone());
                self.advance();
                if matches!(self.peek(), Token::Pipe) {
                    self.advance();
                } else {
                    break;
                }
            }

            // Expect )
            self.expect(&Token::RParen);
            self.skip_newlines();

            // Parse body until ;; or ;& or ;;& or esac
            let body = if matches!(
                self.peek(),
                Token::DoubleSemi | Token::SemiAmp | Token::DoubleSemiAmp | Token::Esac
            ) {
                None
            } else {
                Some(self.parse_list())
            };

            let terminator = match self.peek().clone() {
                Token::DoubleSemi => {
                    self.advance();
                    CaseTerminator::Break
                }
                Token::SemiAmp => {
                    self.advance();
                    CaseTerminator::Fallthrough
                }
                Token::DoubleSemiAmp => {
                    self.advance();
                    CaseTerminator::Continue
                }
                _ => CaseTerminator::Break,
            };

            self.skip_newlines();
            arms.push(CaseArm {
                patterns,
                body,
                terminator,
            });
        }

        self.expect(&Token::Esac);

        Command::Case { word, arms }
    }

    fn parse_function_def(&mut self) -> Command {
        self.advance(); // skip 'function'
        self.skip_newlines();

        let name = if let Token::Word(w) = self.advance() {
            w.to_str()
        } else {
            String::new()
        };

        // Optional ()
        if matches!(self.peek(), Token::LParen) {
            self.advance();
            self.expect(&Token::RParen);
        }

        self.skip_newlines();
        let body = self.parse_command();

        Command::FunctionDef {
            name,
            body: Box::new(body),
        }
    }

    fn parse_subshell(&mut self) -> Command {
        self.advance(); // skip (
        self.skip_newlines();
        let body = self.parse_list();
        self.skip_newlines();
        self.expect(&Token::RParen);

        Command::Subshell(Box::new(body))
    }

    fn parse_brace_group(&mut self) -> Command {
        self.advance(); // skip {
        self.skip_newlines();
        let body = self.parse_list();
        self.skip_newlines();
        self.expect(&Token::RBrace);

        Command::BraceGroup(Box::new(body))
    }
}

use super::ast::{ParameterOperator, WordPart};
use super::glob::{glob_replace, glob_strip_prefix, glob_strip_suffix};

/// Resolve a `ParameterExpansionOp` given an env snapshot. If the variable is in
/// env, apply the operator and return a `Literal`. Otherwise return the original part.
pub fn resolve_param_op(
    name: &str,
    op: &ParameterOperator,
    env: &std::collections::HashMap<String, String>,
) -> WordPart {
    let val = match env.get(name) {
        Some(v) => v.as_str(),
        None => {
            return WordPart::ParameterExpansionOp {
                name: name.to_string(),
                op: op.clone(),
            };
        }
    };

    let result = match op {
        ParameterOperator::Length => val.len().to_string(),
        ParameterOperator::StripPrefix { longest, pattern } => {
            glob_strip_prefix(pattern, val, *longest).to_string()
        }
        ParameterOperator::StripSuffix { longest, pattern } => {
            glob_strip_suffix(pattern, val, *longest).to_string()
        }
        ParameterOperator::Replace {
            all,
            pattern,
            replacement,
        } => glob_replace(pattern, val, replacement, *all),
        ParameterOperator::Default { colon, value } => {
            if *colon {
                // ${VAR:-val}: use default if unset or empty
                if val.is_empty() {
                    value.clone()
                } else {
                    val.to_string()
                }
            } else {
                // ${VAR-val}: use default if unset (var is set, so use val)
                val.to_string()
            }
        }
        ParameterOperator::Alternative { colon, value } => {
            if *colon {
                // ${VAR:+val}: use alternative if set and non-empty
                if val.is_empty() {
                    String::new()
                } else {
                    value.clone()
                }
            } else {
                // ${VAR+val}: use alternative if set (var is set)
                value.clone()
            }
        }
        ParameterOperator::Error { .. } => {
            // Variable is set, so no error; resolve to the value
            val.to_string()
        }
        ParameterOperator::Assign { .. } => {
            // Variable is set, so no assignment; resolve to the value
            val.to_string()
        }
        ParameterOperator::Substring { offset, length } => {
            let off: isize = offset.trim().parse().unwrap_or(0);
            let chars: Vec<char> = val.chars().collect();
            let start = if off < 0 {
                (chars.len() as isize + off).max(0) as usize
            } else {
                (off as usize).min(chars.len())
            };
            match length {
                Some(len_str) => {
                    let len: usize = len_str.trim().parse().unwrap_or(chars.len());
                    let end = (start + len).min(chars.len());
                    chars[start..end].iter().collect()
                }
                None => chars[start..].iter().collect(),
            }
        }
        ParameterOperator::Uppercase { all } => {
            if *all {
                val.to_uppercase()
            } else {
                let mut chars = val.chars();
                match chars.next() {
                    Some(c) => c.to_uppercase().to_string() + chars.as_str(),
                    None => String::new(),
                }
            }
        }
        ParameterOperator::Lowercase { all } => {
            if *all {
                val.to_lowercase()
            } else {
                let mut chars = val.chars();
                match chars.next() {
                    Some(c) => c.to_lowercase().to_string() + chars.as_str(),
                    None => String::new(),
                }
            }
        }
    };
    WordPart::Literal(result)
}

// Segmentation — split a shell command at top-level operators for display.
// This is a presentation concern: used by the CLI to colorize command segments
// independently.

use crate::lexer::{Lexer, Token};

/// A segment of a shell command for display purposes.
#[derive(Debug, Clone)]
pub struct Segment {
    /// Byte range in the original input.
    pub start: usize,
    pub end: usize,
    /// True if this segment is an operator (|, &&, ||, ;, &), false if a command.
    pub is_operator: bool,
}

/// Split a shell command into segments at top-level operators.
/// Returns alternating command and operator segments with their byte ranges.
pub fn segment(input: &str) -> Vec<Segment> {
    let mut lex = Lexer::new(input);
    let tokens = lex.tokenize_with_offsets();

    let mut segments = Vec::new();
    let mut depth: i32 = 0;
    let mut cmd_start: Option<usize> = None;

    for (tok, byte_off) in &tokens {
        match tok {
            Token::Eof => {
                // Flush any pending command segment
                if let Some(start) = cmd_start {
                    let end = input[start..].trim_end().len() + start;
                    if end > start {
                        segments.push(Segment {
                            start,
                            end,
                            is_operator: false,
                        });
                    }
                }
            }
            // Depth-increasing tokens
            Token::LParen
            | Token::If
            | Token::For
            | Token::While
            | Token::Until
            | Token::Case
            | Token::Do
            | Token::LBrace => {
                depth += 1;
                if cmd_start.is_none() {
                    cmd_start = Some(*byte_off);
                }
            }
            // Depth-decreasing tokens
            Token::RParen | Token::Fi | Token::Done | Token::Esac | Token::RBrace => {
                depth -= 1;
                if cmd_start.is_none() {
                    cmd_start = Some(*byte_off);
                }
            }
            // Top-level operators split segments
            Token::Pipe | Token::And | Token::Or | Token::Semi | Token::Amp if depth <= 0 => {
                // Flush the command segment before this operator
                if let Some(start) = cmd_start.take() {
                    let end = trim_end_offset(input, start, *byte_off);
                    if end > start {
                        segments.push(Segment {
                            start,
                            end,
                            is_operator: false,
                        });
                    }
                }
                // Add the operator segment
                let op_len = match tok {
                    Token::And | Token::Or => 2,
                    _ => 1,
                };
                segments.push(Segment {
                    start: *byte_off,
                    end: byte_off + op_len,
                    is_operator: true,
                });
            }
            // Newlines are treated like semicolons at depth 0
            Token::Newline if depth <= 0 => {
                if let Some(start) = cmd_start.take() {
                    let end = trim_end_offset(input, start, *byte_off);
                    if end > start {
                        segments.push(Segment {
                            start,
                            end,
                            is_operator: false,
                        });
                    }
                }
            }
            // Everything else is part of a command
            _ => {
                if cmd_start.is_none() {
                    cmd_start = Some(*byte_off);
                }
            }
        }
    }

    segments
}

/// Find the end of a command segment by trimming trailing whitespace.
fn trim_end_offset(input: &str, start: usize, operator_start: usize) -> usize {
    let between = &input[start..operator_start];
    start + between.trim_end().len()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn segment_empty_input() {
        let segs = segment("");
        assert!(segs.is_empty());
    }

    #[test]
    fn segment_whitespace_only() {
        let segs = segment("   \t  ");
        assert!(segs.is_empty());
    }

    #[test]
    fn segment_single_command() {
        let segs = segment("ls -la");
        assert_eq!(segs.len(), 1);
        assert!(!segs[0].is_operator);
        assert_eq!(segs[0].start, 0);
        assert_eq!(segs[0].end, 6);
    }

    #[test]
    fn segment_simple_pipe() {
        let input = "cat file | grep foo";
        let segs = segment(input);
        assert_eq!(segs.len(), 3);
        // "cat file"
        assert!(!segs[0].is_operator);
        assert_eq!(&input[segs[0].start..segs[0].end], "cat file");
        // "|"
        assert!(segs[1].is_operator);
        assert_eq!(segs[1].end - segs[1].start, 1);
        // "grep foo"
        assert!(!segs[2].is_operator);
        assert_eq!(&input[segs[2].start..segs[2].end], "grep foo");
    }

    #[test]
    fn segment_and_operator() {
        let segs = segment("make && make install");
        assert_eq!(segs.len(), 3);
        // "make"
        assert!(!segs[0].is_operator);
        // "&&" (2 chars)
        assert!(segs[1].is_operator);
        assert_eq!(segs[1].end - segs[1].start, 2);
        // "make install"
        assert!(!segs[2].is_operator);
    }

    #[test]
    fn segment_or_operator() {
        let segs = segment("test -f file || echo missing");
        assert_eq!(segs.len(), 3);
        assert!(segs[1].is_operator);
        assert_eq!(segs[1].end - segs[1].start, 2);
    }

    #[test]
    fn segment_semicolon() {
        let segs = segment("echo a; echo b");
        assert_eq!(segs.len(), 3);
        assert!(segs[1].is_operator);
        assert_eq!(segs[1].end - segs[1].start, 1);
    }

    #[test]
    fn segment_ampersand_background() {
        let segs = segment("sleep 10 &");
        assert_eq!(segs.len(), 2);
        assert!(!segs[0].is_operator);
        assert!(segs[1].is_operator);
        assert_eq!(segs[1].end - segs[1].start, 1);
    }

    #[test]
    fn segment_multiple_operators() {
        let segs = segment("a && b || c");
        assert_eq!(segs.len(), 5);
        assert!(!segs[0].is_operator); // "a"
        assert!(segs[1].is_operator); // "&&"
        assert!(!segs[2].is_operator); // "b"
        assert!(segs[3].is_operator); // "||"
        assert!(!segs[4].is_operator); // "c"
    }

    #[test]
    fn segment_parens_not_split() {
        // Parenthesized commands should NOT be split at operators inside
        let segs = segment("(echo a && echo b)");
        assert_eq!(segs.len(), 1);
        assert!(!segs[0].is_operator);
    }

    #[test]
    fn segment_braces_not_split() {
        // Brace groups should NOT be split at operators inside
        let segs = segment("{ echo a; echo b; }");
        assert_eq!(segs.len(), 1);
        assert!(!segs[0].is_operator);
    }

    #[test]
    fn segment_if_statement_not_split() {
        let segs = segment("if true; then echo yes; fi");
        assert_eq!(segs.len(), 1);
        assert!(!segs[0].is_operator);
    }

    #[test]
    fn segment_for_loop_not_split() {
        let segs = segment("for x in a b; do echo $x; done");
        assert_eq!(segs.len(), 1);
        assert!(!segs[0].is_operator);
    }

    #[test]
    fn segment_while_loop_not_split() {
        let segs = segment("while read line; do echo $line; done");
        assert_eq!(segs.len(), 1);
        assert!(!segs[0].is_operator);
    }

    #[test]
    fn segment_case_statement_not_split() {
        let segs = segment("case $x in a) echo A;; esac");
        assert_eq!(segs.len(), 1);
        assert!(!segs[0].is_operator);
    }

    #[test]
    fn segment_mixed_parens_and_operators() {
        // Parens don't prevent splitting at top level
        let segs = segment("(echo a) | cat");
        assert_eq!(segs.len(), 3);
        assert!(!segs[0].is_operator);
        assert!(segs[1].is_operator);
        assert!(!segs[2].is_operator);
    }

    #[test]
    fn segment_newline_treated_as_separator() {
        let segs = segment("echo a\necho b");
        assert_eq!(segs.len(), 2);
        assert!(!segs[0].is_operator);
        assert!(!segs[1].is_operator);
    }

    #[test]
    fn segment_trims_trailing_whitespace() {
        let segs = segment("ls   ");
        assert_eq!(segs.len(), 1);
        assert_eq!(segs[0].end, 2); // "ls" not "ls   "
    }

    #[test]
    fn segment_leading_whitespace_preserved_in_output() {
        let segs = segment("  ls");
        assert_eq!(segs.len(), 1);
        assert_eq!(segs[0].start, 2); // starts at first non-whitespace
        assert_eq!(segs[0].end, 4); // "ls"
    }

    #[test]
    fn segment_trim_end_offset_basic() {
        assert_eq!(trim_end_offset("hello world", 0, 11), 11);
    }

    #[test]
    fn segment_trim_end_offset_trims_space() {
        assert_eq!(trim_end_offset("hello   ", 0, 8), 5);
    }

    #[test]
    fn segment_trim_end_offset_middle() {
        assert_eq!(trim_end_offset("a && b", 0, 1), 1); // "a" at start
    }

    #[test]
    fn segment_complex_pipeline() {
        let segs = segment("cat file | sort | uniq -c");
        assert_eq!(segs.len(), 5);
        assert!(!segs[0].is_operator);
        assert!(segs[1].is_operator);
        assert!(!segs[2].is_operator);
        assert!(segs[3].is_operator);
        assert!(!segs[4].is_operator);
    }

    #[test]
    fn segment_quotes_and_escapes() {
        // Quotes should be part of the command
        let segs = segment("echo 'hello world' | cat");
        assert_eq!(segs.len(), 3);
        assert!(!segs[0].is_operator);
        assert!(segs[1].is_operator);
        assert!(!segs[2].is_operator);
    }

    #[test]
    fn segment_redirections() {
        // Redirections should be part of the command segment
        let segs = segment("cat < input.txt > output.txt");
        assert_eq!(segs.len(), 1);
        assert!(!segs[0].is_operator);
    }

    #[test]
    fn segment_empty_between_operators() {
        // Edge case: what happens with empty command?
        let segs = segment("&& ls");
        assert_eq!(segs.len(), 2);
        assert!(segs[0].is_operator);
        assert!(!segs[1].is_operator);
    }

    #[test]
    fn segment_only_operators() {
        let segs = segment("&& ||");
        assert_eq!(segs.len(), 2);
        assert!(segs[0].is_operator);
        assert!(segs[1].is_operator);
    }

    #[test]
    fn segment_closing_token_starts_command() {
        // When a closing token is encountered and cmd_start is None,
        // it should start a new command segment
        let segs = segment(") echo hi");
        assert_eq!(segs.len(), 1);
        assert!(!segs[0].is_operator);
        assert_eq!(segs[0].start, 0);
    }

    #[test]
    fn segment_done_starts_command() {
        let segs = segment("done echo hi");
        assert_eq!(segs.len(), 1);
        assert!(!segs[0].is_operator);
    }

    #[test]
    fn segment_fi_starts_command() {
        let segs = segment("fi echo hi");
        assert_eq!(segs.len(), 1);
        assert!(!segs[0].is_operator);
    }

    #[test]
    fn segment_esac_starts_command() {
        let segs = segment("esac echo hi");
        assert_eq!(segs.len(), 1);
        assert!(!segs[0].is_operator);
    }

    #[test]
    fn segment_rbrace_starts_command() {
        let segs = segment("} echo hi");
        assert_eq!(segs.len(), 1);
        assert!(!segs[0].is_operator);
    }
}

