                matches!(&r.target, RedirectionTarget::File(w) if w.to_str().contains("foo"))
                    || matches!(&r.target, RedirectionTarget::Fd(_))
            }));
        }
        _ => {
            // May be parsed differently; just ensure it doesn't panic
        }
    }
}

